fn verifier_assessment_field<'a>(
    object: &'a serde_json::Map<String, serde_json::Value>,
    keys: &[&str],
) -> Option<&'a serde_json::Value> {
    keys.iter().find_map(|key| object.get(*key))
}

fn parse_verifier_repair_targets_value(
    value: &serde_json::Value,
) -> Vec<ParsedVerifierRepairTarget> {
    match value {
        serde_json::Value::Array(values) => values
            .iter()
            .filter_map(parse_verifier_repair_target_value)
            .take(3)
            .collect(),
        _ => parse_verifier_repair_target_value(value)
            .into_iter()
            .collect(),
    }
}

fn parse_verifier_secondary_targets_value(value: &serde_json::Value) -> Vec<String> {
    match value {
        serde_json::Value::Array(values) => values
            .iter()
            .filter_map(parse_verifier_repair_target_value)
            .map(|target| target.path)
            .take(3)
            .collect(),
        _ => parse_verifier_repair_target_value(value)
            .map(|target| vec![target.path])
            .unwrap_or_default(),
    }
}

fn parse_verifier_repair_target_value(
    value: &serde_json::Value,
) -> Option<ParsedVerifierRepairTarget> {
    if let Some(path) = value.as_str() {
        let path = path.trim();
        if path.is_empty() || path == "null" || path == "unknown" {
            return None;
        }
        return Some(ParsedVerifierRepairTarget {
            path: path.to_string(),
            confidence: 0.5,
            reason: "diagnostic LLM selected this repair target".to_string(),
        });
    }
    let object = value.as_object()?;
    let path = verifier_assessment_field(
        object,
        &[
            "path",
            "target",
            "file",
            "filename",
            "target_file",
            "target_path",
        ],
    )
    .and_then(serde_json::Value::as_str)?
    .trim();
    if path.is_empty() || path == "null" || path == "unknown" {
        return None;
    }
    let confidence = object
        .get("confidence")
        .and_then(|value| {
            value
                .as_f64()
                .or_else(|| value.as_str().and_then(|text| text.parse::<f64>().ok()))
        })
        .filter(|value| value.is_finite())
        .unwrap_or(0.5)
        .clamp(0.0, 1.0);
    let reason = object
        .get("reason")
        .or_else(|| object.get("intent"))
        .or_else(|| object.get("summary"))
        .or_else(|| object.get("cause"))
        .and_then(serde_json::Value::as_str)
        .map(|reason| compact_verifier_failure_text(reason, VERIFIER_DIAGNOSTIC_MAX_REASON_CHARS))
        .filter(|reason| !reason.is_empty())
        .unwrap_or_else(|| "diagnostic LLM selected this repair target".to_string());
    Some(ParsedVerifierRepairTarget {
        path: path.to_string(),
        confidence,
        reason,
    })
}

fn verifier_diagnostic_failure_kind_from_str(
    value: &str,
) -> Option<super::VerifierDiagnosticFailureKind> {
    match value.trim().to_ascii_lowercase().as_str() {
        "dependency_missing" | "import_or_dependency" | "dependency" | "missing_dependency" => {
            Some(super::VerifierDiagnosticFailureKind::DependencyMissing)
        }
        "local_import_contract_mismatch" | "local_symbol_import_error" | "contract_mismatch" => {
            Some(super::VerifierDiagnosticFailureKind::LocalImportContractMismatch)
        }
        "compile_or_syntax_error" | "compile_or_syntax" | "compile" | "syntax" => {
            Some(super::VerifierDiagnosticFailureKind::CompileOrSyntaxError)
        }
        "assertion_mismatch" | "assertion_failure" | "assertion" | "test_assertion" => {
            Some(super::VerifierDiagnosticFailureKind::AssertionMismatch)
        }
        "runtime_error" | "runtime" => Some(super::VerifierDiagnosticFailureKind::RuntimeError),
        "test_bug" | "bad_test" => Some(super::VerifierDiagnosticFailureKind::TestBug),
        "config_or_verifier_error"
        | "missing_verifier_or_config"
        | "missing_verifier"
        | "config" => Some(super::VerifierDiagnosticFailureKind::ConfigOrVerifierError),
        "unknown" => Some(super::VerifierDiagnosticFailureKind::Unknown),
        _ => None,
    }
}

fn verifier_failure_type_for_diagnostic_kind(
    kind: super::VerifierDiagnosticFailureKind,
    fallback: super::VerifierFailureType,
) -> super::VerifierFailureType {
    match kind {
        super::VerifierDiagnosticFailureKind::DependencyMissing => {
            super::VerifierFailureType::ImportOrDependency
        }
        // Issue #638 (設計判断 #3): LocalImportContractMismatch → ImportOrDependency
        // so `verifier_repair_preferred_local_import_source` fires correctly when
        // the derived_failure_type is passed to the helper.
        super::VerifierDiagnosticFailureKind::LocalImportContractMismatch => {
            super::VerifierFailureType::ImportOrDependency
        }
        super::VerifierDiagnosticFailureKind::RuntimeError
        | super::VerifierDiagnosticFailureKind::TestBug => super::VerifierFailureType::RuntimeError,
        super::VerifierDiagnosticFailureKind::CompileOrSyntaxError => {
            super::VerifierFailureType::CompileOrSyntax
        }
        super::VerifierDiagnosticFailureKind::AssertionMismatch => {
            super::VerifierFailureType::AssertionFailure
        }
        super::VerifierDiagnosticFailureKind::ConfigOrVerifierError => {
            super::VerifierFailureType::MissingVerifierOrConfig
        }
        super::VerifierDiagnosticFailureKind::Unknown => fallback,
    }
}

fn artifact_role_from_assessment_str(value: &str) -> Option<super::task_contract::ArtifactRole> {
    match value.trim().to_ascii_lowercase().as_str() {
        "implementation" | "impl" | "code" | "source" => {
            Some(super::task_contract::ArtifactRole::Implementation)
        }
        "test" | "tests" => Some(super::task_contract::ArtifactRole::Test),
        "usage_docs" | "docs" | "documentation" | "readme" => {
            Some(super::task_contract::ArtifactRole::UsageDocs)
        }
        "setup" | "config" | "dependency" | "dependencies" => {
            Some(super::task_contract::ArtifactRole::Setup)
        }
        "unknown" => None,
        _ => None,
    }
}

fn recovery_target_hint_for_existing_path(
    work_root: &Path,
    raw_path: &str,
    reason: &str,
) -> Option<super::task_contract::RecoveryTargetHint> {
    if !verifier_diagnostic_path_input_is_safe(raw_path) {
        return None;
    }
    let resolved = resolve_user_path(work_root, raw_path).ok()?;
    if !resolved.is_file() {
        return None;
    }
    let root = std::fs::canonicalize(work_root).unwrap_or_else(|_| work_root.to_path_buf());
    let canonical = std::fs::canonicalize(&resolved).ok()?;
    if !canonical.is_file() {
        return None;
    }
    let relative = canonical.strip_prefix(root).ok()?;
    let path = relative.to_string_lossy().replace('\\', "/");
    if is_ignored_workspace_display_path(&path) {
        return None;
    }
    let category = super::completion_evidence::classify_repo_edit_path(Path::new(&path));
    let role = artifact_role_from_repo_edit_category(category)?;
    Some(super::task_contract::RecoveryTargetHint {
        role,
        path,
        reason: reason.to_string(),
    })
}

/// Issue #647 (Phase C, §4.4 / §5.1): Owned admission context for every
/// `RecoveryTargetHint` promotion path. Path-local predicates (DR3-001) so
/// the SSOT gate evaluates `turn_edited_relative_paths.contains(path)` /
/// `repo_edit_has_post_scaffold_delta(path)` for *the hint's own path*, not
/// a turn-global signal that would falsely promote unrelated files.
///
/// `verifier_passed_in_scope` is omitted from the context per DR1-006:
/// every callsite in this Issue is "trying to repair a hint" — by
/// construction the verifier has not yet passed for the active scope, so
/// `admit_repair_target_hint` fixes that flag to `false` literally. When a
/// future Issue introduces post-success repair paths the field can be
/// re-introduced on this struct without touching the SSOT function shape.
pub(super) struct RepairTargetAdmissionContext<'a> {
    pub(super) work_root: &'a Path,
    pub(super) scope: &'a super::task_workspace_scope::TaskWorkspaceScope,
    pub(super) edited_this_session_for: &'a dyn Fn(&str) -> bool,
    pub(super) scaffold_changed_for: &'a dyn Fn(&str) -> bool,
}

#[cfg(test)]
fn admission_always_true(_: &str) -> bool {
    true
}

#[cfg(test)]
fn admission_always_false(_: &str) -> bool {
    false
}

impl<'a> RepairTargetAdmissionContext<'a> {
    /// Test-only helper: build an admission context whose predicates always
    /// promote the hint to `Owned` (edited_this_session=true). Lets fixtures
    /// keep their existing repair-target assertions while still routing
    /// through the SSOT gate (S7-004 / DR2-001).
    #[cfg(test)]
    pub(super) fn owned_for_test(
        work_root: &'a Path,
        scope: &'a super::task_workspace_scope::TaskWorkspaceScope,
    ) -> Self {
        Self {
            work_root,
            scope,
            edited_this_session_for: &admission_always_true,
            scaffold_changed_for: &admission_always_false,
        }
    }
}

/// Issue #647 (Phase C, §5.1 SSOT): Owned admission gate for any
/// `RecoveryTargetHint` heading downstream into the repair-job pipeline.
/// Every hint-promotion source category (6 categories in §5.1) routes
/// through this single function so the `OwnershipInputs` invariants stay
/// consistent (path-local predicates evaluated against `hint.path`,
/// `verifier_passed_in_scope` fixed to `false` per DR1-006).
pub(super) fn admit_repair_target_hint(
    hint: super::task_contract::RecoveryTargetHint,
    ctx: &RepairTargetAdmissionContext<'_>,
) -> Option<super::task_contract::RecoveryTargetHint> {
    let path = hint.path.clone();
    let inputs = super::artifact_ownership::OwnershipInputs {
        work_root: ctx.work_root,
        relative_path: &path,
        scope: ctx.scope,
        edited_this_session: (ctx.edited_this_session_for)(&path),
        scaffold_changed: (ctx.scaffold_changed_for)(&path),
        verifier_passed_in_scope: false,
        // Issue #661 (Task 3.1): RepairJob target admission is NOT one of
        // the 4 verifier-path SSOT sites — keep `disabled()` so repair
        // target acceptance semantics are unchanged.
        nested_test_admission: super::artifact_ownership::NestedTestAdmission::default(),
    };
    match super::artifact_ownership::classify_ownership(inputs) {
        super::artifact_ownership::ArtifactOwnership::Owned => Some(hint),
        super::artifact_ownership::ArtifactOwnership::CandidateOnly
        | super::artifact_ownership::ArtifactOwnership::OutOfScope => None,
    }
}

fn recovery_target_hint_for_diagnostic_path(
    work_root: &Path,
    raw_path: &str,
    reason: &str,
    failure_kind: super::VerifierDiagnosticFailureKind,
    admission: &RepairTargetAdmissionContext<'_>,
) -> Option<super::task_contract::RecoveryTargetHint> {
    if let Some(hint) = recovery_target_hint_for_existing_path(work_root, raw_path, reason) {
        if hint.role == super::task_contract::ArtifactRole::Setup
            && !failure_kind.allows_setup_target()
        {
            return None;
        }
        // Issue #647 (§5.1 stage 2): Owned admission gate at the function exit.
        // Path 1 of the 6 source categories: diagnostic LLM-proposed paths.
        return admit_repair_target_hint(hint, admission);
    }
    recovery_target_hint_for_missing_setup_path(
        work_root,
        raw_path,
        reason,
        failure_kind,
        admission,
    )
}

fn recovery_target_hint_for_missing_setup_path(
    work_root: &Path,
    raw_path: &str,
    reason: &str,
    failure_kind: super::VerifierDiagnosticFailureKind,
    admission: &RepairTargetAdmissionContext<'_>,
) -> Option<super::task_contract::RecoveryTargetHint> {
    if !failure_kind.allows_setup_target() {
        return None;
    }
    let path = raw_path.trim().replace('\\', "/");
    if !verifier_diagnostic_path_input_is_safe(&path)
        || !admission.scope.contains(&path)
        || !diagnostic_missing_setup_path_is_controller_writable(&path)
    {
        return None;
    }
    let resolved = resolve_user_path(work_root, &path).ok()?;
    if resolved.exists() {
        return None;
    }
    if !super::artifact_ownership::nearest_existing_ancestor_within_work_root(work_root, &resolved)
    {
        return None;
    }
    Some(super::task_contract::RecoveryTargetHint {
        role: super::task_contract::ArtifactRole::Setup,
        path,
        reason: reason.to_string(),
    })
}

fn diagnostic_missing_setup_path_is_controller_writable(path: &str) -> bool {
    matches!(path, "pyproject.toml")
}

fn verifier_diagnostic_missing_setup_candidates(
    work_root: &Path,
    context: &super::repair_job::RepairJob,
    active_request: &str,
) -> Vec<super::task_contract::RecoveryTargetHint> {
    if !python_verifier_output_missing_external_dependency(work_root, context) {
        return Vec::new();
    }
    let scope = super::task_workspace_scope::TaskWorkspaceScope::detect(work_root, active_request);
    let no_prior_edit = |_: &str| false;
    let admission = RepairTargetAdmissionContext {
        work_root,
        scope: &scope,
        edited_this_session_for: &no_prior_edit,
        scaffold_changed_for: &no_prior_edit,
    };
    recovery_target_hint_for_missing_setup_path(
        work_root,
        "pyproject.toml",
        "Python verifier cannot import a third-party dependency and no setup manifest is available",
        super::VerifierDiagnosticFailureKind::DependencyMissing,
        &admission,
    )
    .into_iter()
    .collect()
}

fn python_verifier_output_missing_external_dependency(
    work_root: &Path,
    context: &super::repair_job::RepairJob,
) -> bool {
    if !verifier_output_or_command_looks_like_pytest(&context.command, &context.output_excerpt) {
        return false;
    }
    python_missing_external_dependency_name(work_root, &context.output_excerpt).is_some()
}

fn python_missing_external_dependency_name(work_root: &Path, output: &str) -> Option<String> {
    for line in output.lines() {
        let lower = line.to_ascii_lowercase();
        let Some(marker_index) = lower.find("no module named") else {
            continue;
        };
        let candidate = line[marker_index + "no module named".len()..].trim();
        let candidate = candidate
            .trim_matches(|ch: char| {
                ch == '\''
                    || ch == '"'
                    || ch == ':'
                    || ch == '.'
                    || ch == ','
                    || ch == '`'
                    || ch == ' '
            })
            .split_whitespace()
            .next()
            .unwrap_or_default()
            .trim_matches(|ch: char| {
                ch == '\'' || ch == '"' || ch == ':' || ch == '.' || ch == ','
            });
        if !python_module_name_for_import_validation_is_safe(candidate) {
            continue;
        }
        let top_level = candidate.split('.').next().unwrap_or_default();
        if top_level.is_empty()
            || work_root.join(format!("{top_level}.py")).is_file()
            || work_root.join(top_level).is_dir()
        {
            continue;
        }
        return Some(candidate.to_string());
    }
    None
}

fn recovery_target_hint_for_missing_local_module_path(
    work_root: &Path,
    raw_path: &str,
    reason: &str,
    admission: &RepairTargetAdmissionContext<'_>,
) -> Option<super::task_contract::RecoveryTargetHint> {
    let path = raw_path.trim();
    if !verifier_diagnostic_path_input_is_safe(path) {
        return None;
    }
    if Path::new(path)
        .components()
        .any(|component| match component {
            std::path::Component::Normal(name) => {
                super::task_workspace_scope::is_workspace_ignored_dir(&name.to_string_lossy())
            }
            _ => false,
        })
    {
        return None;
    }
    if Path::new(path)
        .extension()
        .and_then(|ext| ext.to_str())
        .is_none_or(|ext| !ext.eq_ignore_ascii_case("py"))
    {
        return None;
    }
    if !admission.scope.contains(path) {
        return None;
    }
    let resolved = resolve_user_path(work_root, path).ok()?;
    if resolved.exists() {
        return recovery_target_hint_for_existing_path(work_root, path, reason);
    }
    if !super::artifact_ownership::nearest_existing_ancestor_within_work_root(work_root, &resolved)
    {
        return None;
    }
    Some(super::task_contract::RecoveryTargetHint {
        role: super::task_contract::ArtifactRole::Implementation,
        path: path.to_string(),
        reason: reason.to_string(),
    })
}

fn missing_python_module_name_from_output(output: &str) -> Option<String> {
    for quote in ["'", "\""] {
        let marker = format!("No module named {quote}");
        let Some(start) = output.find(&marker) else {
            continue;
        };
        let rest = &output[start + marker.len()..];
        let Some(end) = rest.find(quote) else {
            continue;
        };
        let module = rest[..end].trim();
        if module.split('.').count() < 2 {
            continue;
        }
        if module.split('.').all(|part| {
            !part.is_empty()
                && part
                    .chars()
                    .all(|ch| ch == '_' || ch.is_ascii_alphanumeric())
                && !part.chars().next().is_some_and(|ch| ch.is_ascii_digit())
        }) {
            return Some(module.to_string());
        }
    }
    None
}

fn missing_python_module_workspace_path(work_root: &Path, module: &str) -> Option<String> {
    let mut parts = module.split('.');
    let top = parts.next()?;
    if !work_root.join(top).is_dir() {
        return None;
    }
    if !work_root.join(top).join("__init__.py").is_file() {
        return None;
    }
    let relative = format!("{}.py", module.replace('.', "/"));
    let parent = Path::new(&relative).parent()?;
    if !work_root.join(parent).is_dir() {
        return None;
    }
    Some(relative)
}

fn verifier_repair_missing_local_module_provider(
    context: &super::repair_job::RepairJob,
    derived_failure_type: super::VerifierFailureType,
    admission: &RepairTargetAdmissionContext<'_>,
) -> Option<super::task_contract::RecoveryTargetHint> {
    if derived_failure_type != super::VerifierFailureType::ImportOrDependency {
        return None;
    }
    let module = missing_python_module_name_from_output(&context.output_excerpt)?;
    if !workspace_implementation_imports_python_module(admission.work_root, &module) {
        return None;
    }
    let path = missing_python_module_workspace_path(admission.work_root, &module)?;
    recovery_target_hint_for_missing_local_module_path(
        admission.work_root,
        &path,
        "verifier output names a missing local module provider",
        admission,
    )
}

/// Issue #647 / CB-017 A''' (Commit 3, CR-2 V2): merge legacy
/// `ParsedVerifierRepairAssessment` targets into the first cluster of a
/// `SemanticFailureReport` **only when every cluster is targetless**.
///
/// Policy (all-or-nothing): partial output (some clusters target_paths, some
/// not) is never merged — targetless clusters are skipped downstream by
/// `first_repairable_cluster` / `next_repairable_cluster`. Merging into a
/// random "first" cluster on partial output would break the LLM-supplied
/// cluster ↔ path binding.
///
/// `role_hint` is always `None` because `ParsedVerifierRepairTarget` does
/// not carry a role; the admitted hint's role is decided later by
/// `recovery_target_hint_for_existing_path` (CR-3 V2). Each appended
/// candidate's `raw_path` / `reason` is sanitized via
/// `sanitize_repair_job_text_with_char_cap` so the parse-boundary invariant
/// (same SSOT as `parse_semantic_failure_report`) holds.
pub(super) fn merge_legacy_targets_into_clusters(
    report: &mut super::semantic_failure::SemanticFailureReport,
    parsed: &ParsedVerifierRepairAssessment,
) {
    let all_empty = report
        .failure_clusters
        .iter()
        .all(|c| c.proposed_target_candidates.is_empty());
    if !all_empty {
        return;
    }
    let Some(first_cluster) = report.failure_clusters.first_mut() else {
        return;
    };
    for target in &parsed.repair_targets {
        if first_cluster.proposed_target_candidates.len()
            >= super::semantic_failure::MAX_PROPOSED_TARGETS_PER_CLUSTER
        {
            break;
        }
        first_cluster.proposed_target_candidates.push(
            super::semantic_failure::RawClusterTargetCandidate {
                raw_path: super::repair_job::sanitize_repair_job_text_with_char_cap(
                    &target.path,
                    super::semantic_failure::MAX_RAW_PATH_CHARS,
                ),
                role_hint: None,
                reason: super::repair_job::sanitize_repair_job_text_with_char_cap(
                    &target.reason,
                    240,
                ),
            },
        );
    }
    for entry in &parsed.repair_plan {
        if first_cluster.proposed_target_candidates.len()
            >= super::semantic_failure::MAX_PROPOSED_TARGETS_PER_CLUSTER
        {
            break;
        }
        // Dedup-by-path: a path already appended via `repair_targets` is not
        // re-appended via `repair_plan`. We compare against the sanitized
        // entry that was pushed (the same SSOT is applied to the new entry
        // below) so a path string that differs only in trailing whitespace /
        // control chars still dedupes correctly.
        let sanitized_path = super::repair_job::sanitize_repair_job_text_with_char_cap(
            &entry.path,
            super::semantic_failure::MAX_RAW_PATH_CHARS,
        );
        if first_cluster
            .proposed_target_candidates
            .iter()
            .any(|c| c.raw_path == sanitized_path)
        {
            continue;
        }
        first_cluster.proposed_target_candidates.push(
            super::semantic_failure::RawClusterTargetCandidate {
                raw_path: sanitized_path,
                role_hint: None,
                reason: super::repair_job::sanitize_repair_job_text_with_char_cap(
                    &entry.reason,
                    240,
                ),
            },
        );
    }
    for path in &parsed.secondary_targets {
        if first_cluster.proposed_target_candidates.len()
            >= super::semantic_failure::MAX_PROPOSED_TARGETS_PER_CLUSTER
        {
            break;
        }
        let sanitized_path = super::repair_job::sanitize_repair_job_text_with_char_cap(
            path,
            super::semantic_failure::MAX_RAW_PATH_CHARS,
        );
        if first_cluster
            .proposed_target_candidates
            .iter()
            .any(|c| c.raw_path == sanitized_path)
        {
            continue;
        }
        first_cluster.proposed_target_candidates.push(
            super::semantic_failure::RawClusterTargetCandidate {
                raw_path: sanitized_path,
                role_hint: None,
                reason: "diagnostic secondary target".to_string(),
            },
        );
    }
}

/// Issue #647 / CB-017 A''' (Commit 3, CR-1 V2 / CR-3 V2 / CR-5):
/// for every failure cluster, admit each `proposed_target_candidate` via
/// the SSOT `recovery_target_hint_for_diagnostic_path` (which composes
/// syntactic safety + Owned admission + setup-target gating), dedup the
/// admitted hints by `(role, path)`, and sort them with the
/// authority/failure-kind decision table in
/// [`sort_admitted_by_authority_role_priority`].
///
/// CR-3 V2: `candidate.role_hint` is **advisory only** — it is never passed
/// to the admission helper. The admitted hint's role is decided by
/// `recovery_target_hint_for_existing_path`'s path classification.
///
/// CR-1 V2: the admission SSOT is invoked exactly once per candidate. We do
/// NOT additionally call `admit_repair_target_hint` after the fact (that
/// would double-gate Owned).
pub(super) fn enrich_failure_clusters_with_admitted_targets(
    report: &mut super::semantic_failure::SemanticFailureReport,
    work_root: &Path,
    admission_ctx: &RepairTargetAdmissionContext<'_>,
    spec_authority: super::spec_authority::SpecAuthority,
) {
    let failure_kind = report.failure_kind;
    for cluster in report.failure_clusters.iter_mut() {
        let mut admitted: Vec<super::task_contract::RecoveryTargetHint> = Vec::new();
        for candidate in cluster.proposed_target_candidates.iter() {
            // recovery_target_hint_for_diagnostic_path is the SSOT — it
            // composes syntactic safety + Owned admission via
            // admit_repair_target_hint. role_hint is intentionally not
            // forwarded (CR-3 V2).
            if let Some(hint) = recovery_target_hint_for_diagnostic_path(
                work_root,
                &candidate.raw_path,
                &candidate.reason,
                failure_kind,
                admission_ctx,
            ) {
                admitted.push(hint);
            }
        }
        // (role, path) dedup — Codex nice-to-have 2.
        admitted.sort_by(|a, b| (a.role, &a.path).cmp(&(b.role, &b.path)));
        admitted.dedup_by(|a, b| a.role == b.role && a.path == b.path);
        // Role priority sort (TestBug override / SetupRepair defensive /
        // default impl-first). Stable sort with (rank, path) tie-breaker.
        sort_admitted_by_authority_role_priority(&mut admitted, spec_authority, failure_kind);
        cluster.admitted_cluster_targets = admitted;
    }
}

/// Issue #647 / CB-017 A''' (Commit 3, CR-5 V2): stable role-priority sort
/// for an `admitted_cluster_targets` slice.
///
/// Decision table:
///
/// | `failure_kind` / authority                                | Order                                          |
/// |-----------------------------------------------------------|------------------------------------------------|
/// | `TestBug` (override)                                      | Test > Impl > UsageDocs > Setup                |
/// | `DependencyMissing` / `ConfigOrVerifierError` (defensive) | Setup > Impl > UsageDocs > Test                |
/// | `AssertionMismatch` + User/Behavior contract              | Impl > Test > UsageDocs > Setup                |
/// | `AssertionMismatch` + Impl/interface/LLM-test authority   | Test > Impl > UsageDocs > Setup                |
/// | everything else                                           | Impl > UsageDocs > Setup > Test                |
///
/// The sort is stable and uses `(rank, path)` as the sort key so ties (two
/// targets of the same role) resolve in deterministic path order.
pub(super) fn sort_admitted_by_authority_role_priority(
    admitted: &mut [super::task_contract::RecoveryTargetHint],
    spec_authority: super::spec_authority::SpecAuthority,
    failure_kind: super::VerifierDiagnosticFailureKind,
) {
    let primary_rank_for = |role: super::task_contract::ArtifactRole| -> u8 {
        if matches!(failure_kind, super::VerifierDiagnosticFailureKind::TestBug) {
            return match role {
                super::task_contract::ArtifactRole::Test => 0,
                super::task_contract::ArtifactRole::Implementation => 1,
                super::task_contract::ArtifactRole::UsageDocs => 2,
                super::task_contract::ArtifactRole::Setup => 3,
            };
        }
        if matches!(
            failure_kind,
            super::VerifierDiagnosticFailureKind::DependencyMissing
                | super::VerifierDiagnosticFailureKind::ConfigOrVerifierError
        ) {
            return match role {
                super::task_contract::ArtifactRole::Setup => 0,
                super::task_contract::ArtifactRole::Implementation => 1,
                super::task_contract::ArtifactRole::UsageDocs => 2,
                super::task_contract::ArtifactRole::Test => 3,
            };
        }
        if matches!(
            failure_kind,
            super::VerifierDiagnosticFailureKind::AssertionMismatch
        ) {
            return match spec_authority {
                super::spec_authority::SpecAuthority::UserRequest
                | super::spec_authority::SpecAuthority::BehaviorContract => match role {
                    super::task_contract::ArtifactRole::Implementation => 0,
                    super::task_contract::ArtifactRole::Test => 1,
                    super::task_contract::ArtifactRole::UsageDocs => 2,
                    super::task_contract::ArtifactRole::Setup => 3,
                },
                super::spec_authority::SpecAuthority::VerifiedPublicInterface
                | super::spec_authority::SpecAuthority::ImplementationContract
                | super::spec_authority::SpecAuthority::LlmGeneratedTest => match role {
                    super::task_contract::ArtifactRole::Test => 0,
                    super::task_contract::ArtifactRole::Implementation => 1,
                    super::task_contract::ArtifactRole::UsageDocs => 2,
                    super::task_contract::ArtifactRole::Setup => 3,
                },
            };
        }
        match role {
            super::task_contract::ArtifactRole::Implementation => 0,
            super::task_contract::ArtifactRole::UsageDocs => 1,
            super::task_contract::ArtifactRole::Setup => 2,
            super::task_contract::ArtifactRole::Test => 3,
        }
    };
    admitted.sort_by(|a, b| {
        let pa = primary_rank_for(a.role);
        let pb = primary_rank_for(b.role);
        pa.cmp(&pb).then_with(|| a.path.cmp(&b.path))
    });
}

fn diagnostic_target_allowed_by_confidence(
    hint: &super::task_contract::RecoveryTargetHint,
    confidence: f64,
    failure_kind: super::VerifierDiagnosticFailureKind,
    probable_cause_role: Option<super::task_contract::ArtifactRole>,
    do_not_edit_tests_without_evidence: bool,
) -> bool {
    if hint.role != super::task_contract::ArtifactRole::Test || !do_not_edit_tests_without_evidence
    {
        return true;
    }
    if matches!(failure_kind, super::VerifierDiagnosticFailureKind::TestBug)
        || probable_cause_role == Some(super::task_contract::ArtifactRole::Test)
    {
        return confidence >= 0.60;
    }
    confidence >= 0.85
}

fn verifier_diagnostic_path_input_is_safe(raw_path: &str) -> bool {
    let path = raw_path.trim();
    if path.is_empty()
        || path.contains('\0')
        || Path::new(path).is_absolute()
        || is_ignored_workspace_display_path(path)
    {
        return false;
    }
    !Path::new(path)
        .components()
        .any(|component| matches!(component, std::path::Component::ParentDir))
}

fn verifier_repair_preferred_local_import_source(
    context: &super::repair_job::RepairJob,
    // Issue #638 (設計判断 #3): caller passes the assessment-derived failure type
    // so this helper is not gated on `context.failure_type` (which is `Unknown`
    // after the parser scope reduction in Task 1.2). Production callers MUST pass
    // `verifier_failure_type_for_diagnostic_kind(failure_kind, context.failure_type)`.
    derived_failure_type: super::VerifierFailureType,
    admission: &RepairTargetAdmissionContext<'_>,
) -> Option<super::task_contract::RecoveryTargetHint> {
    if derived_failure_type != super::VerifierFailureType::ImportOrDependency {
        return None;
    }
    let lower = context.output_excerpt.to_ascii_lowercase();
    let local_import_mismatch = lower.contains("cannot import name")
        || lower.contains("unresolved import")
        || lower.contains("has no exported member")
        || lower.contains("attempted import error")
        || lower.contains("is not exported from");
    if !local_import_mismatch {
        return None;
    }
    let hint = context.target_hint.as_ref()?;
    let promoted = if hint.role == super::task_contract::ArtifactRole::Implementation {
        Some(super::task_contract::RecoveryTargetHint {
            reason: "local import contract mismatch names this provider/source file".to_string(),
            ..hint.clone()
        })
    } else {
        None
    }?;
    // Issue #647 (§5.1 stage 2): Owned admission gate. Path 4 of the
    // 6 source categories: local-import-contract-derived hints.
    admit_repair_target_hint(promoted, admission)
}

fn verifier_repair_stale_assertion_test_target(
    context: &super::repair_job::RepairJob,
    selected_path: Option<&str>,
    // Issue #638 (設計判断 #3): caller passes the assessment-derived failure type
    // so this helper is not gated on `context.failure_type` (which is `Unknown`
    // after the parser scope reduction in Task 1.2). Production callers MUST pass
    // `verifier_failure_type_for_diagnostic_kind(failure_kind, context.failure_type)`.
    derived_failure_type: super::VerifierFailureType,
    admission: &RepairTargetAdmissionContext<'_>,
) -> Option<super::task_contract::RecoveryTargetHint> {
    if derived_failure_type != super::VerifierFailureType::AssertionFailure {
        return None;
    }
    let previous_non_test_repair_was_unresolved = matches!(
        context.rerun_outcome,
        Some(
            super::VerifierRepairRerunOutcome::SameFailureRemaining
                | super::VerifierRepairRerunOutcome::Worsened
                | super::VerifierRepairRerunOutcome::Improved
        )
    );
    if !previous_non_test_repair_was_unresolved {
        return None;
    }
    let previous_target = context.repair_target_hint.as_ref()?;
    if previous_target.role == super::task_contract::ArtifactRole::Test {
        return None;
    }
    if selected_path.is_some_and(|path| path != previous_target.path) {
        return None;
    }
    let failure_target = context.target_hint.as_ref()?;
    if failure_target.role != super::task_contract::ArtifactRole::Test
        || failure_target.path == previous_target.path
    {
        return None;
    }
    let promoted = super::task_contract::RecoveryTargetHint {
        reason: "same assertion failure remained after a non-test repair; inspect generated test setup or expectations".to_string(),
        ..failure_target.clone()
    };
    // Issue #647 (§5.1 stage 2): Owned admission gate. Path 5 of the
    // 6 source categories: stale-assertion test re-target.
    admit_repair_target_hint(promoted, admission)
}

/// Issue #647 (Phase D): extract the JSON object value from a diagnostic LLM
/// reply, mirroring the SSOT preamble used by
/// [`parse_verifier_repair_assessment_reply`] (strip `<think>` tags →
/// trim/truncate → find the outermost `{ … }`). Returns `None` on any
/// extraction or `serde_json` parse failure.
///
/// Phase D wires this helper into `run_verifier_diagnostic_pass` so the
/// existing `ParsedVerifierRepairAssessment` parse and the new
/// `parse_semantic_failure_report` parse share an identical JSON-extraction
/// boundary. Keeping the extraction logic colocated avoids drift between
/// the two parse paths.
fn extract_diagnostic_reply_json_value(reply: &str) -> Option<serde_json::Value> {
    let stripped = strip_think_tags(reply);
    let trimmed = truncate(stripped.trim(), VERIFIER_DIAGNOSTIC_MAX_OUTPUT_BYTES);
    let json_text = if trimmed.starts_with('{') && trimmed.ends_with('}') {
        trimmed.clone()
    } else {
        let start = trimmed.find('{')?;
        let end = trimmed.rfind('}')?;
        if end <= start {
            return None;
        }
        trimmed[start..=end].to_string()
    };
    serde_json::from_str(&json_text).ok()
}

/// Issue #647 (Phase D / D.1): parse a diagnostic LLM reply into an
/// [`super::semantic_failure::SemanticFailureReport`]. Independent of the
/// legacy `ParsedVerifierRepairAssessment` parse — a failure here returns
/// `None` and the caller proceeds with `semantic_plan = None` (DR3-005), so
/// the existing `VerifierRepairAssessment` / legacy repair-target selection
/// is **not** disturbed.
fn parse_semantic_failure_report_from_reply(
    reply: &str,
) -> Option<super::semantic_failure::SemanticFailureReport> {
    let value = extract_diagnostic_reply_json_value(reply)?;
    super::semantic_failure::parse_semantic_failure_report(&value).or_else(|| {
        let object = value.as_object()?;
        let nested = object
            .get("SemanticFailureReport")
            .or_else(|| object.get("semantic_failure_report"))?;
        let mut nested = nested.clone();
        let nested_object = nested.as_object_mut()?;
        if !nested_object.contains_key("failure_kind") {
            let failure_kind = object
                .get("failure_kind")
                .or_else(|| object.get("failure_type"))?;
            nested_object.insert("failure_kind".to_string(), failure_kind.clone());
        }
        if !nested_object.contains_key("preferred_repair_role")
            && let Some(role) = object
                .get("probable_cause_role")
                .or_else(|| object.get("root_cause_role"))
                .or_else(|| object.get("role"))
        {
            nested_object.insert("preferred_repair_role".to_string(), role.clone());
        }
        if !nested_object.contains_key("confidence")
            && let Some(confidence) = object.get("confidence")
        {
            nested_object.insert("confidence".to_string(), confidence.clone());
        }
        super::semantic_failure::parse_semantic_failure_report(&nested)
    })
}

/// Issue #647 (MF1): deterministic fallback that synthesizes a
/// [`super::semantic_failure::SemanticFailureReport`] from a legacy
/// [`ParsedVerifierRepairAssessment`] and the surrounding [`RepairJob`].
///
/// MF1 production motivation: most LLMs today emit only the legacy fields
/// (`probable_cause_role` / `failure_kind` / `repair_plan` / `summary`), so
/// `parse_semantic_failure_report_from_reply` returns `None` and the
/// `semantic_plan` slot stays empty in production. This helper recovers a
/// usable `SemanticFailureReport` from the legacy parse so semantic repair
/// planning kicks in for every diagnostic pass, not only when the LLM
/// volunteered the extended schema.
///
/// Determinism contract: same `(parsed, repair_job)` input MUST produce the
/// same `SemanticFailureReport`. No randomness, no clock, no LLM-derived
/// confidence — `confidence` is fixed at the deterministic legacy default
/// (`LEGACY_FALLBACK_CONFIDENCE`).
///
/// Returns `None` only when the legacy parsed result cannot produce a
/// meaningful failure cluster (e.g. `failure_signature` is empty AND
/// `output_excerpt` is empty AND there is no summary text). In practice the
/// caller passes a `RepairJob` with at least a non-empty `failure_signature`
/// (built by `verifier_repair_context_from_failure`), so the helper returns
/// `Some` for every realistic production input.
fn build_semantic_failure_report_from_legacy(
    parsed: &ParsedVerifierRepairAssessment,
    repair_job: &super::repair_job::RepairJob,
) -> Option<super::semantic_failure::SemanticFailureReport> {
    use super::semantic_failure::{
        ContractConflict, MAX_CLUSTER_TEXT_CHARS, MAX_REPAIR_HYPOTHESIS_CHARS,
        build_failure_cluster_from_observation,
    };

    // Map legacy probable_cause_role → preferred_repair_role; default to
    // Implementation (deterministic) when the LLM did not supply one.
    let preferred_repair_role = parsed
        .probable_cause_role
        .unwrap_or(super::task_contract::ArtifactRole::Implementation);

    // Build a single failure cluster from the legacy RepairJob signal. The
    // cluster_key is generated locally via the SSOT cluster builder, so it
    // never depends on attacker-controlled text.
    let observed = if !repair_job.failure_signature.is_empty() {
        repair_job.failure_signature.as_str()
    } else {
        repair_job.output_excerpt.as_str()
    };
    let expected = parsed.summary.as_deref().unwrap_or("");
    // input_shape / assertion_shape are not surfaced by the legacy schema;
    // we leave them empty so the SSOT shape-normalizer collapses them
    // identically across legacy inputs (deterministic cluster key).
    let cluster = build_failure_cluster_from_observation(
        observed,
        expected,
        "",
        "",
        &[preferred_repair_role],
        // CB-017 A''' (Commit 2): legacy fallback synthesizes a cluster with
        // **no** proposed target candidates; the merge step (Commit 3) will
        // append legacy `parsed.repair_targets` here under the all-empty
        // policy. Keep `Vec::new()` to preserve existing behavior.
        Vec::new(),
    );

    // contract_conflict is sourced from the legacy summary — it lives in the
    // `implementation` slot because the legacy summary historically described
    // implementation-side findings. The other two slots are empty so the
    // schema's invariant ("each side sanitized to MAX_CLUSTER_TEXT_CHARS")
    // still holds without us inventing test / docs content.
    let contract_conflict = ContractConflict {
        implementation: super::repair_job::sanitize_repair_job_text_with_char_cap(
            parsed.summary.as_deref().unwrap_or(""),
            MAX_CLUSTER_TEXT_CHARS,
        ),
        test: String::new(),
        usage_docs: String::new(),
    };

    // repair_hypothesis: first entry of the legacy repair_plan (intent +
    // path), truncated by the SSOT sanitize entry. Falls back to the legacy
    // summary when the plan is empty.
    let raw_hypothesis = parsed
        .repair_plan
        .first()
        .map(|target| {
            if target.reason.is_empty() {
                target.path.clone()
            } else {
                format!("{}: {}", target.path, target.reason)
            }
        })
        .or_else(|| parsed.summary.clone())
        .unwrap_or_default();
    let repair_hypothesis = super::repair_job::sanitize_repair_job_text_with_char_cap(
        &raw_hypothesis,
        MAX_REPAIR_HYPOTHESIS_CHARS,
    );

    /// Deterministic legacy default — never LLM-supplied. Chosen as 0.5 so
    /// downstream consumers can distinguish "fallback" reports from
    /// "LLM-supplied" reports by checking for the midpoint value.
    const LEGACY_FALLBACK_CONFIDENCE: f32 = 0.5;

    Some(super::semantic_failure::SemanticFailureReport {
        failure_kind: parsed.failure_kind,
        failure_clusters: vec![cluster],
        contract_conflict,
        preferred_repair_role,
        repair_hypothesis,
        confidence: LEGACY_FALLBACK_CONFIDENCE,
    })
}

/// Build a semantic report from the already-admitted legacy assessment.
///
/// This is the bridge for cases where the raw diagnostic payload cannot
/// produce an admitted semantic target, but the legacy assessment boundary
/// later selects a safe `repair_target_hint` from admitted sources such as
/// verifier output or changed-file hints. Test edits are guarded by
/// `SemanticRepairPlan`, so the selected legacy target and the semantic plan
/// must not drift.
fn build_semantic_failure_report_from_legacy_assessment(
    assessment: &super::VerifierRepairAssessment,
    repair_job: &super::repair_job::RepairJob,
) -> Option<super::semantic_failure::SemanticFailureReport> {
    use super::semantic_failure::{
        ContractConflict, MAX_CLUSTER_TEXT_CHARS, MAX_REPAIR_HYPOTHESIS_CHARS,
        build_failure_cluster_from_observation,
    };

    let mut admitted_targets = Vec::<super::task_contract::RecoveryTargetHint>::new();
    if let Some(target) = assessment.repair_target_hint.as_ref() {
        admitted_targets.push(target.clone());
    }
    for target in assessment
        .repair_plan
        .iter()
        .chain(assessment.needed_reads.iter())
    {
        if !admitted_targets
            .iter()
            .any(|existing| existing.role == target.role && existing.path == target.path)
        {
            admitted_targets.push(target.clone());
        }
    }
    if admitted_targets.is_empty() {
        return None;
    }

    let preferred_repair_role = assessment
        .repair_target_hint
        .as_ref()
        .map(|target| target.role)
        .or(assessment.probable_cause_role)
        .or_else(|| admitted_targets.first().map(|target| target.role))?;
    let failure_kind = semantic_failure_kind_for_legacy_assessment(
        assessment.failure_kind,
        repair_job.failure_type,
        preferred_repair_role,
    );

    let observed = if !repair_job.failure_signature.is_empty() {
        repair_job.failure_signature.as_str()
    } else {
        repair_job.output_excerpt.as_str()
    };
    let expected = assessment.summary.as_deref().unwrap_or("");
    let mut cluster = build_failure_cluster_from_observation(
        observed,
        expected,
        "",
        "",
        &[preferred_repair_role],
        Vec::new(),
    );
    cluster.admitted_cluster_targets = admitted_targets;

    let summary = assessment.summary.as_deref().unwrap_or("");
    let contract_conflict = ContractConflict {
        implementation: super::repair_job::sanitize_repair_job_text_with_char_cap(
            summary,
            MAX_CLUSTER_TEXT_CHARS,
        ),
        test: String::new(),
        usage_docs: String::new(),
    };
    let raw_hypothesis = assessment
        .repair_target_hint
        .as_ref()
        .or_else(|| assessment.repair_plan.first())
        .or_else(|| assessment.needed_reads.first())
        .map(|target| {
            if target.reason.is_empty() {
                target.path.clone()
            } else {
                format!("{}: {}", target.path, target.reason)
            }
        })
        .or_else(|| assessment.summary.clone())
        .unwrap_or_default();
    let repair_hypothesis = super::repair_job::sanitize_repair_job_text_with_char_cap(
        &raw_hypothesis,
        MAX_REPAIR_HYPOTHESIS_CHARS,
    );

    Some(super::semantic_failure::SemanticFailureReport {
        failure_kind,
        failure_clusters: vec![cluster],
        contract_conflict,
        preferred_repair_role,
        repair_hypothesis,
        // Same deterministic midpoint used by the raw legacy fallback. This
        // value marks the report as controller-derived, not LLM-supplied.
        confidence: 0.5,
    })
}

fn semantic_failure_kind_for_legacy_assessment(
    assessment_kind: super::VerifierDiagnosticFailureKind,
    verifier_failure_type: super::VerifierFailureType,
    preferred_repair_role: super::task_contract::ArtifactRole,
) -> super::VerifierDiagnosticFailureKind {
    if preferred_repair_role != super::task_contract::ArtifactRole::Test {
        return assessment_kind;
    }
    if !matches!(
        assessment_kind,
        super::VerifierDiagnosticFailureKind::DependencyMissing
            | super::VerifierDiagnosticFailureKind::ConfigOrVerifierError
    ) {
        return assessment_kind;
    }
    if matches!(
        verifier_failure_type,
        super::VerifierFailureType::AssertionFailure | super::VerifierFailureType::RuntimeError
    ) {
        return super::VerifierDiagnosticFailureKind::TestBug;
    }
    assessment_kind
}

/// Issue #647 (Phase D / D.2 + D.3): build a [`super::repair_job::SemanticRepairPlan`]
/// from a parsed [`super::semantic_failure::SemanticFailureReport`].
///
/// Returns `None` when:
/// - `dispatch_target(report) == SetupRepair` (D.3): DependencyMissing /
///   ConfigOrVerifierError are routed to the existing setup-repair /
///   `MissingVerifierJob` pipeline; no SemanticRepairPlan is constructed.
/// - `report.failure_clusters` is empty (no cluster to attack; the caller
///   keeps `semantic_plan = None`).
///
/// `expected_improvement` is initialized to `None` — Phase E fills it after
/// the verifier rerun.
/// Issue #647 (SF1 / V3): construct a `SpecAuthorityInput` for the
/// production diagnostic pass by funneling four independent signals into
/// the resolver:
///
/// 1. `has_behavior_contract` — derived from
///    `task_contract::TaskContract::from_request` on the active request.
/// 2. `has_user_request_match` — derived from the SF1 V3.1 explicit-spec
///    keyword detector ([`spec_authority::detect_explicit_spec_in_user_request`]).
/// 3. `has_verified_public_interface` — derived from the SF1 V3.2
///    history hint detector
///    ([`spec_authority::detect_verified_public_interface_from_history`]),
///    which today reads the turn-local "verifier already passed once"
///    bit and never reaches outside the current actor-loop iteration.
/// 4. `consensus` — derived from the SF1 V3.3 string-match heuristic
///    ([`spec_authority::detect_consensus_from_contract_conflict`]) over
///    the parsed `SemanticFailureReport.contract_conflict` fields. `None`
///    when no report is available yet (e.g. legacy parse).
///
/// `is_newly_generated_task` stays `true` per the SF1 acceptance — Issue
/// #647 treats every turn as "newly generated" until a future Issue
/// plumbs a real detector. The resolver's newly-generated short-circuit
/// only fires when `consensus` is `None`, so the V3.3 detector
/// automatically demotes the short-circuit when a real tie-break exists.
///
/// The helper lives here (not in `spec_authority.rs`) because it crosses
/// the `task_contract` / `spec_authority` / `semantic_failure` module
/// boundaries; the resolver itself stays input-only and decoupled from
/// `TaskContract` and `SemanticFailureReport`.
fn build_spec_authority_input_for_active_request(
    active_request: Option<&str>,
    semantic_report: Option<&super::semantic_failure::SemanticFailureReport>,
    agent_history_hint: super::spec_authority::AgentHistoryHint,
) -> super::spec_authority::SpecAuthorityInput {
    let has_behavior_contract = active_request
        .map(|request| {
            let contract = super::task_contract::TaskContract::from_request(request);
            super::required_behavior::behavior_contract_has_repair_authority(&contract)
        })
        .unwrap_or(false);
    let has_user_request_match = active_request
        .map(super::spec_authority::detect_explicit_spec_in_user_request)
        .unwrap_or(false);
    let has_verified_public_interface =
        super::spec_authority::detect_verified_public_interface_from_history(agent_history_hint);
    let consensus = semantic_report.and_then(|report| {
        super::spec_authority::detect_consensus_from_contract_conflict(
            &report.contract_conflict.implementation,
            &report.contract_conflict.test,
            &report.contract_conflict.usage_docs,
        )
    });
    super::spec_authority::SpecAuthorityInput {
        has_user_request_match,
        has_behavior_contract,
        has_verified_public_interface,
        is_newly_generated_task: true,
        consensus,
    }
}

/// Issue #647 (SF1): test-only wrapper that builds the plan with the
/// default `SpecAuthorityInput`. Production code passes its own
/// `SpecAuthorityInput` directly to
/// [`build_semantic_repair_plan_from_report_with_authority_input`] (so the
/// `has_behavior_contract` flag can be derived from the active request);
/// the test suite uses this convenience wrapper to keep older test
/// fixtures unchanged.
#[cfg(test)]
fn build_semantic_repair_plan_from_report(
    report: super::semantic_failure::SemanticFailureReport,
) -> Option<super::repair_job::SemanticRepairPlan> {
    // Issue #647 (CB-015): test-only wrapper threads `0` as the
    // generation snapshot — tests that pre-date CB-015 model a
    // first-build "no prior re-diagnostic" state where the plan was
    // created against generation 0.
    build_semantic_repair_plan_from_report_with_authority_input(
        report,
        default_spec_authority_input(),
        0,
    )
}

/// Issue #647 (SF1): production default for `SpecAuthorityInput` when the
/// build helper is called without explicit caller context.
///
/// - `has_user_request_match`: `false` (detection is a future Issue).
/// - `has_behavior_contract`: `false` (the caller that has the
///   `TaskContract` will pass an overridden input via
///   `build_semantic_repair_plan_from_report_with_authority_input`).
/// - `has_verified_public_interface`: `false` (S5-005 dead variant).
/// - `is_newly_generated_task`: `true` — Issue acceptance treats every
///   turn as "newly generated" until a future Issue plumbs a real
///   detector.
/// - `consensus`: `None` — consensus detection is a future Issue.
#[cfg(test)]
fn default_spec_authority_input() -> super::spec_authority::SpecAuthorityInput {
    super::spec_authority::SpecAuthorityInput {
        has_user_request_match: false,
        has_behavior_contract: false,
        has_verified_public_interface: false,
        is_newly_generated_task: true,
        consensus: None,
    }
}

/// Issue #647 (SF1): variant that lets the caller pass an explicit
/// `SpecAuthorityInput` (so a future Issue can wire the actual
/// `RequiredBehaviorContract` / consensus detection signals).
fn build_semantic_repair_plan_from_report_with_authority_input(
    report: super::semantic_failure::SemanticFailureReport,
    authority_input: super::spec_authority::SpecAuthorityInput,
    assessment_generation: u32,
) -> Option<super::repair_job::SemanticRepairPlan> {
    // D.3: DependencyMissing / ConfigOrVerifierError → setup repair path,
    // no semantic plan.
    if super::semantic_failure::dispatch_target(&report)
        == super::semantic_failure::SemanticDispatchTarget::SetupRepair
    {
        return None;
    }
    // 1 RepairJob = 1 cluster (slot reuse, Phase E). Pick the first
    // **repairable** cluster — CB-017 A''' (Commit 3, CR-6 V2) skips
    // targetless clusters (admitted_cluster_targets empty) so the plan is
    // always anchored to a cluster the controller can actually attack.
    // When tests build a fixture report *without* running the enrich step,
    // every cluster looks targetless; fall back to the legacy "first cluster"
    // behavior in that case so the existing test suite stays green.
    let failure_cluster_id = super::repair_job::first_repairable_cluster(&report)
        .or_else(|| report.failure_clusters.first())?
        .cluster_key
        .clone();
    // Issue #647 (SF1): SpecAuthority is now resolved through the
    // structured `resolve()` SSOT so impl/test/README are treated as
    // equally authoritative on newly generated tasks. Pre-SF1 the
    // candidate set was hard-coded to `[ImplementationContract,
    // LlmGeneratedTest]`, which always elected ImplementationContract and
    // let the repair editor rewrite tests to match buggy impl.
    let spec_authority = super::spec_authority::resolve(&authority_input);
    Some(super::repair_job::SemanticRepairPlan {
        semantic_cause: report.failure_kind,
        spec_authority,
        preferred_repair_role: report.preferred_repair_role,
        repair_hypothesis: report.repair_hypothesis.clone(),
        failure_cluster_id,
        expected_improvement: None,
        semantic_report: report,
        // Issue #647 (CB-015): coil the caller-provided generation. The
        // production callsite in `run_verifier_diagnostic_pass` passes the
        // RepairJob's pre-bump generation so this plan is fresh relative
        // to the assessment we are about to write into the slot.
        assessment_generation_at_creation: assessment_generation,
    })
}

fn build_verifier_repair_pipeline_shadow_payload(
    session_id: &str,
    model: &str,
    model_role: &'static str,
    context: &super::repair_job::RepairJob,
    parsed: &ParsedVerifierRepairAssessment,
    assessment: &super::VerifierRepairAssessment,
) -> serde_json::Value {
    let packet = failure_packet_for_verifier_pipeline_shadow(context, assessment);
    let brief_result = super::repair_brief::repair_brief_from_legacy_diagnostic(
        legacy_repair_brief_input_for_shadow(parsed, assessment),
    );

    match brief_result {
        Ok(brief) => {
            let action_payload = match super::repair_action::build_repair_action(&brief, &packet) {
                Ok(action) => serde_json::json!({
                    "status": "accepted",
                    "target_role": action.target_role.label(),
                    "target_path_hash": stable_path_hash(&action.target_path),
                    "allowed_change_kind": action.allowed_change_kind.as_str(),
                    "source_of_truth": action.source_of_truth.as_str(),
                    "budget": action.budget,
                }),
                Err(err) => serde_json::json!({
                    "status": "rejected",
                    "reason": err.as_str(),
                }),
            };
            let brief_target = brief.repair_target.as_ref();
            serde_json::json!({
                "session_id": session_id,
                "model": model,
                "model_role": model_role,
                "packet_signature": packet.failure_signature,
                "candidate_count": packet.candidate_artifacts.len(),
                "brief": {
                    "status": "accepted",
                    "source": brief.source.as_str(),
                    "target_role": brief_target.map(|target| target.role.label()),
                    "target_path_hash": brief_target.map(|target| stable_path_hash(&target.path)),
                    "allowed_change_kind": brief.allowed_change_kind.as_str(),
                    "source_of_truth": brief.source_of_truth.as_str(),
                    "confidence": brief.confidence,
                },
                "action": action_payload,
            })
        }
        Err(err) => serde_json::json!({
            "session_id": session_id,
            "model": model,
            "model_role": model_role,
            "packet_signature": packet.failure_signature,
            "candidate_count": packet.candidate_artifacts.len(),
            "brief": {
                "status": "rejected",
                "reason": err.as_str(),
            },
            "action": {
                "status": "skipped",
                "reason": "brief_rejected",
            },
        }),
    }
}

fn failure_packet_for_verifier_pipeline_shadow(
    context: &super::repair_job::RepairJob,
    assessment: &super::VerifierRepairAssessment,
) -> super::failure_packet::FailurePacket {
    let mut candidate_artifacts = Vec::new();
    for (hint, reason) in assessment
        .repair_target_hint
        .iter()
        .map(|hint| (hint, "diagnostic selected repair target"))
        .chain(
            assessment
                .repair_plan
                .iter()
                .map(|hint| (hint, "diagnostic repair plan candidate")),
        )
        .chain(
            assessment
                .needed_reads
                .iter()
                .map(|hint| (hint, "diagnostic read candidate")),
        )
        .chain(
            context
                .changed_file_hints
                .iter()
                .map(|hint| (hint, "changed workspace file candidate")),
        )
    {
        push_shadow_candidate_artifact(&mut candidate_artifacts, hint, reason);
    }

    super::failure_packet::FailurePacket::new(
        &context.command,
        assessment.failure_kind.as_str(),
        &context.output_excerpt,
        Vec::new(),
        Vec::new(),
        candidate_artifacts,
        Vec::new(),
    )
}

fn verifier_repair_action_payload_for_context(
    context: &super::repair_job::RepairJob,
) -> Option<serde_json::Value> {
    let action = verifier_repair_action_for_context(context)?;
    Some(serde_json::json!({
        "target_role": action.target_role.label(),
        "target_path": action.target_path,
        "allowed_change_kind": action.allowed_change_kind.as_str(),
        "source_of_truth": action.source_of_truth.as_str(),
        "budget": action.budget,
        "brief_confidence": action.brief_confidence,
    }))
}

fn verifier_repair_action_for_context(
    context: &super::repair_job::RepairJob,
) -> Option<super::repair_action::RepairAction> {
    let assessment = context.assessment.as_ref()?;
    let packet = failure_packet_for_verifier_pipeline_shadow(context, assessment);
    let brief = super::repair_brief::repair_brief_from_legacy_diagnostic(
        legacy_repair_brief_input_from_assessment(assessment, 0.6),
    )
    .ok()?;
    super::repair_action::build_repair_action(&brief, &packet).ok()
}

fn push_shadow_candidate_artifact(
    candidate_artifacts: &mut Vec<super::failure_packet::CandidateArtifact>,
    hint: &super::task_contract::RecoveryTargetHint,
    reason: &str,
) {
    let candidate = super::failure_packet::CandidateArtifact::new(hint.role, &hint.path, reason);
    if candidate.path.is_empty() {
        return;
    }
    if candidate_artifacts
        .iter()
        .any(|existing| existing.path == candidate.path)
    {
        return;
    }
    candidate_artifacts.push(candidate);
}

fn legacy_repair_brief_input_for_shadow(
    parsed: &ParsedVerifierRepairAssessment,
    assessment: &super::VerifierRepairAssessment,
) -> super::repair_brief::LegacyDiagnosticBriefInput {
    let repair_target = assessment.repair_target_hint.as_ref();
    let repair_target_path = repair_target.map(|target| target.path.clone());
    let repair_target_confidence = repair_target_path
        .as_deref()
        .and_then(|path| parsed_confidence_for_path(parsed, path))
        .or_else(|| repair_target_path.as_ref().map(|_| 0.6));

    let mut input = legacy_repair_brief_input_from_assessment(assessment, 0.6);
    input.probable_cause_role = repair_target
        .map(|target| target.role)
        .or(assessment.probable_cause_role)
        .or(parsed.probable_cause_role);
    input.repair_target_confidence = repair_target_confidence;
    input.summary = assessment
        .summary
        .clone()
        .or_else(|| parsed.summary.clone());
    input
}

fn legacy_repair_brief_input_from_assessment(
    assessment: &super::VerifierRepairAssessment,
    default_confidence: f64,
) -> super::repair_brief::LegacyDiagnosticBriefInput {
    let repair_target = assessment.repair_target_hint.as_ref();
    let repair_target_path = repair_target.map(|target| target.path.clone());
    super::repair_brief::LegacyDiagnosticBriefInput {
        failure_kind: assessment.failure_kind.as_str().to_string(),
        probable_cause_role: repair_target
            .map(|target| target.role)
            .or(assessment.probable_cause_role),
        repair_target_path,
        repair_target_confidence: repair_target.map(|_| default_confidence),
        summary: assessment.summary.clone(),
    }
}

fn parsed_confidence_for_path(parsed: &ParsedVerifierRepairAssessment, path: &str) -> Option<f64> {
    let normalized_path = normalize_shadow_path(path);
    parsed
        .repair_plan
        .iter()
        .chain(parsed.repair_targets.iter())
        .find(|target| normalize_shadow_path(&target.path) == normalized_path)
        .map(|target| target.confidence)
}

fn normalize_shadow_path(path: &str) -> String {
    path.trim()
        .replace('\\', "/")
        .trim_start_matches("./")
        .to_string()
}

/// Boundary helper that converts a parsed diagnostic reply into the
/// legacy `super::VerifierRepairAssessment` value used by the rest of the
/// verifier-repair pipeline.
///
/// # Responsibility boundary (Issue #647 / S3-005 / SF3)
///
/// This function is **the** SSOT boundary for legacy-side assessment
/// construction. The Issue #647 semantic-repair planning lives outside
/// this boundary on purpose:
///
///   * **Legacy boundary (this function)**: builds
///     `VerifierRepairAssessment { failure_kind, failure_type,
///     probable_cause_role, needed_reads, repair_target_hint,
///     repair_plan, summary, source }` only. The 7 existing
///     `VerifierRepairAssessment` struct-literal callsites
///     (turn.rs:15399 / 18785 / 19477 / 19553 / 20230 / 23108 / 23133)
///     are unchanged by Issue #647 — none of them call into the
///     semantic-repair helpers.
///   * **Semantic boundary (outside this function, in
///     [`run_verifier_diagnostic_pass`])**: after this function returns
///     the legacy assessment, the caller separately runs:
///       1. [`parse_semantic_failure_report_from_reply`] on the raw reply
///       2. [`build_semantic_failure_report_from_legacy`] as a
///          deterministic fallback (MF1) when (1) returns `None`
///       3. [`build_semantic_repair_plan_from_report_with_authority_input`]
///          to construct the `SemanticRepairPlan` and write it into
///          `RepairJob.semantic_plan`
///
/// The two boundaries are intentionally kept separate so that:
///   * existing tests pinning the legacy 7 struct-literal callsites
///     remain unaffected (S3-005 unchanged-callsites invariant);
///   * the semantic-repair pipeline can be evolved (new fallback paths,
///     consensus detection, ...) without touching this function.
fn model_assessment_to_verifier_repair_assessment(
    work_root: &Path,
    context: &super::repair_job::RepairJob,
    parsed: ParsedVerifierRepairAssessment,
    admission: &RepairTargetAdmissionContext<'_>,
) -> super::VerifierRepairAssessment {
    let failure_kind = parsed.failure_kind;
    let failure_type =
        verifier_failure_type_for_diagnostic_kind(failure_kind, context.failure_type);
    let repair_candidates = parsed
        .repair_targets
        .iter()
        .filter_map(|target| {
            recovery_target_hint_for_diagnostic_path(
                work_root,
                &target.path,
                &target.reason,
                failure_kind,
                admission,
            )
            .filter(|hint| {
                diagnostic_target_allowed_by_confidence(
                    hint,
                    target.confidence,
                    failure_kind,
                    parsed.probable_cause_role,
                    parsed.do_not_edit_tests_without_evidence,
                )
            })
            .map(|hint| (hint, target.confidence))
        })
        .collect::<Vec<_>>();
    let mut repair_plan = parsed
        .repair_plan
        .iter()
        .filter_map(|target| {
            recovery_target_hint_for_diagnostic_path(
                work_root,
                &target.path,
                &target.reason,
                failure_kind,
                admission,
            )
            .filter(|hint| {
                diagnostic_target_allowed_by_confidence(
                    hint,
                    target.confidence,
                    failure_kind,
                    parsed.probable_cause_role,
                    parsed.do_not_edit_tests_without_evidence,
                )
            })
        })
        .collect::<Vec<_>>();
    if repair_plan.is_empty() {
        repair_plan = repair_candidates
            .iter()
            .map(|(hint, _)| hint.clone())
            .take(3)
            .collect();
    }
    let has_admitted_diagnostic_target = !repair_plan.is_empty() || !repair_candidates.is_empty();
    let secondary_repair_candidates = parsed
        .secondary_targets
        .iter()
        .filter_map(|path| {
            recovery_target_hint_for_diagnostic_path(
                work_root,
                path,
                "diagnostic LLM suggested this secondary target",
                failure_kind,
                admission,
            )
        })
        .collect::<Vec<_>>();
    let changed_repair_candidates = context
        .changed_file_hints
        .iter()
        .filter_map(|hint| admit_repair_target_hint(hint.clone(), admission))
        .collect::<Vec<_>>();
    // Issue #638 (設計判断 #3): pass assessment-derived failure_type to helpers so
    // they gate on the diagnostic classification, not on context.failure_type
    // (which is Unknown after the parser scope reduction).
    if let Some(preferred) =
        verifier_repair_missing_local_module_provider(context, failure_type, admission)
    {
        repair_plan.retain(|hint| hint.path != preferred.path);
        repair_plan.insert(0, preferred);
        repair_plan.truncate(3);
    } else if let Some(preferred) =
        verifier_repair_preferred_local_import_source(context, failure_type, admission)
    {
        repair_plan.retain(|hint| hint.path != preferred.path);
        repair_plan.insert(0, preferred);
        repair_plan.truncate(3);
    }
    let selected_path = repair_plan.first().map(|hint| hint.path.as_str());
    if let Some(test_target) =
        verifier_repair_stale_assertion_test_target(context, selected_path, failure_type, admission)
    {
        repair_plan.retain(|hint| hint.path != test_target.path);
        repair_plan.insert(0, test_target);
        repair_plan.truncate(3);
    }
    if has_admitted_diagnostic_target
        && let Some(preferred) = first_role_kind_compatible_diagnostic_target(
            &repair_plan,
            &repair_candidates,
            &secondary_repair_candidates,
            &changed_repair_candidates,
            failure_kind,
        )
    {
        repair_plan.retain(|hint| hint.path != preferred.path);
        repair_plan.insert(0, preferred);
        repair_plan.truncate(3);
    }
    let needed_reads = repair_candidates
        .iter()
        .map(|(hint, _)| hint.clone())
        .chain(repair_plan.iter().cloned())
        .chain(secondary_repair_candidates.iter().cloned())
        .take(3)
        .collect::<Vec<_>>();
    let repair_target_hint = repair_plan
        .first()
        .cloned()
        .or_else(|| {
            repair_candidates
                .iter()
                .max_by(|(_, a), (_, b)| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal))
                .map(|(hint, _)| hint.clone())
        })
        .or_else(|| {
            // Issue #647 (§5.1): path 6 — `repair_target_hint` fallback from
            // `probable_cause_role`. The candidates here come from
            // `context.changed_file_hints` (path 3) and `needed_reads` (which
            // were themselves already admitted via paths 1/4/5 above). Apply
            // `admit_repair_target_hint` explicitly so the changed-file-hint
            // branch is gated by the SSOT even when the inputs were copied
            // straight off `RepairJob`.
            parsed.probable_cause_role.and_then(|role| {
                needed_reads
                    .iter()
                    .chain(context.changed_file_hints.iter())
                    .find(|hint| {
                        hint.role == role
                            && (hint.role != super::task_contract::ArtifactRole::Setup
                                || failure_kind.allows_setup_target())
                    })
                    .cloned()
                    .and_then(|hint| admit_repair_target_hint(hint, admission))
            })
        });

    super::VerifierRepairAssessment {
        failure_kind,
        failure_type,
        probable_cause_role: parsed.probable_cause_role,
        needed_reads,
        repair_target_hint,
        repair_plan,
        summary: parsed.summary,
        source: super::VerifierRepairAssessmentSource::DiagnosticPass,
    }
}

fn first_role_kind_compatible_diagnostic_target(
    repair_plan: &[super::task_contract::RecoveryTargetHint],
    repair_candidates: &[(super::task_contract::RecoveryTargetHint, f64)],
    secondary_repair_candidates: &[super::task_contract::RecoveryTargetHint],
    changed_repair_candidates: &[super::task_contract::RecoveryTargetHint],
    failure_kind: super::VerifierDiagnosticFailureKind,
) -> Option<super::task_contract::RecoveryTargetHint> {
    repair_plan
        .iter()
        .chain(repair_candidates.iter().map(|(hint, _)| hint))
        .chain(secondary_repair_candidates.iter())
        .chain(changed_repair_candidates.iter())
        .find(|hint| diagnostic_target_role_matches_failure_kind(hint, failure_kind))
        .cloned()
}

fn diagnostic_target_role_matches_failure_kind(
    hint: &super::task_contract::RecoveryTargetHint,
    failure_kind: super::VerifierDiagnosticFailureKind,
) -> bool {
    let kind = super::repair_brief::legacy_kind_to_allowed_change_kind(failure_kind.as_str());
    if kind == super::repair_brief::AllowedChangeKind::InsufficientEvidence {
        return true;
    }
    super::repair_action::allowed_change_kind_allows_target_role(kind, hint.role)
}

#[cfg(test)]
fn verifier_repair_target_hint_from_output(
    work_root: &Path,
    output: &str,
    changed_files: &[String],
) -> Option<super::task_contract::RecoveryTargetHint> {
    verifier_repair_target_candidate_from_output(work_root, output, changed_files)
        .map(|candidate| candidate.hint)
}

fn verifier_repair_target_candidate_from_output(
    work_root: &Path,
    output: &str,
    changed_files: &[String],
) -> Option<VerifierRepairTargetCandidate> {
    let mut candidates = Vec::<VerifierRepairTargetCandidate>::new();
    let mut ordinal = 0usize;

    for line in output.lines() {
        if verifier_output_line_is_non_fatal_warning(line) {
            continue;
        }
        for path in extract_path_like_tokens(line) {
            if let Some(candidate) =
                verifier_repair_candidate_from_path(work_root, path, line, true, ordinal)
            {
                insert_verifier_repair_candidate(&mut candidates, candidate);
                ordinal = ordinal.saturating_add(1);
            }
        }
    }

    for path in changed_files {
        if let Some(candidate) =
            verifier_repair_candidate_from_path(work_root, path, "", false, ordinal)
        {
            insert_verifier_repair_candidate(&mut candidates, candidate);
            ordinal = ordinal.saturating_add(1);
        }
    }

    candidates.into_iter().max_by(|a, b| {
        a.score
            .cmp(&b.score)
            .then_with(|| b.ordinal.cmp(&a.ordinal))
    })
}

fn verifier_repair_candidate_from_path(
    work_root: &Path,
    raw_path: &str,
    source_line: &str,
    from_verifier_output: bool,
    ordinal: usize,
) -> Option<VerifierRepairTargetCandidate> {
    let Ok(resolved) = resolve_user_path(work_root, raw_path) else {
        return None;
    };
    if !resolved.is_file() {
        return None;
    }
    let canonical_root = work_root.canonicalize().ok();
    let relative = if let Some(root) = canonical_root.as_ref() {
        resolved.strip_prefix(root).ok()
    } else {
        resolved.strip_prefix(work_root).ok()
    }?;
    let path = relative.to_string_lossy().replace('\\', "/");
    if is_ignored_workspace_display_path(&path) {
        return None;
    }
    let category = super::completion_evidence::classify_repo_edit_path(std::path::Path::new(&path));
    let role = artifact_role_from_repo_edit_category(category)?;
    let line = from_verifier_output
        .then(|| verifier_line_number_for_path(source_line, raw_path))
        .flatten();
    let role_score = match role {
        super::task_contract::ArtifactRole::Implementation => 30,
        super::task_contract::ArtifactRole::Setup => 25,
        super::task_contract::ArtifactRole::Test => 15,
        super::task_contract::ArtifactRole::UsageDocs => 5,
    };
    let import_provider_score = if from_verifier_output
        && role == super::task_contract::ArtifactRole::Implementation
        && verifier_line_names_import_provider(source_line)
    {
        40
    } else {
        0
    };
    let score = usize::from(from_verifier_output) * 50
        + usize::from(line.is_some()) * 30
        + role_score
        + import_provider_score;
    Some(VerifierRepairTargetCandidate {
        hint: super::task_contract::RecoveryTargetHint {
            role,
            path,
            reason: "verifier output or changed files identify this artifact as repair target"
                .to_string(),
        },
        line,
        score,
        ordinal,
    })
}

fn verifier_line_names_import_provider(line: &str) -> bool {
    let lower = line.to_ascii_lowercase();
    lower.contains("cannot import name")
        || lower.contains("unresolved import")
        || lower.contains("has no exported member")
        || lower.contains("attempted import error")
        || lower.contains("is not exported from")
}

fn insert_verifier_repair_candidate(
    candidates: &mut Vec<VerifierRepairTargetCandidate>,
    candidate: VerifierRepairTargetCandidate,
) {
    if let Some(existing) = candidates
        .iter_mut()
        .find(|existing| existing.hint.path == candidate.hint.path)
    {
        if candidate.score > existing.score
            || (candidate.score == existing.score && candidate.ordinal < existing.ordinal)
        {
            *existing = candidate;
        }
        return;
    }
    candidates.push(candidate);
}

fn verifier_output_line_is_non_fatal_warning(line: &str) -> bool {
    let trimmed = line.trim_start();
    let lower = trimmed.to_ascii_lowercase();
    (lower.contains("warning") || lower.contains("warnings summary"))
        && !lower.starts_with("error")
        && !lower.starts_with("failed ")
        && !lower.starts_with("e   ")
        && !lower.starts_with("e ")
        && !lower.starts_with("thread '")
}

fn verifier_line_number_for_path(line: &str, raw_path: &str) -> Option<usize> {
    let idx = line.find(raw_path)?;
    let rest = &line[idx + raw_path.len()..];
    if let Some(number) = rest.strip_prefix(':').and_then(parse_leading_usize) {
        return Some(number);
    }
    rest.find("line ")
        .and_then(|idx| parse_leading_usize(&rest[idx + "line ".len()..]))
}

fn parse_leading_usize(input: &str) -> Option<usize> {
    let digits = input
        .chars()
        .take_while(|ch| ch.is_ascii_digit())
        .collect::<String>();
    if digits.is_empty() {
        None
    } else {
        digits.parse().ok()
    }
}

fn verifier_failure_error_kind(output: &str) -> Option<String> {
    let failed_tests = verifier_failed_tests_signature(output);
    let exception = verifier_primary_exception_signature(output);
    match (failed_tests, exception) {
        (Some(failed_tests), Some(exception)) => {
            return Some(compact_verifier_failure_text(
                &format!("{failed_tests} exception:{exception}"),
                220,
            ));
        }
        (Some(failed_tests), None) => return Some(failed_tests),
        (None, Some(exception)) => return Some(exception),
        (None, None) => {}
    }
    for line in output.lines() {
        let trimmed = line.trim();
        let candidate = trimmed
            .strip_prefix("E   ")
            .or_else(|| trimmed.strip_prefix("E "))
            .or_else(|| trimmed.strip_prefix("error:"))
            .or_else(|| trimmed.strip_prefix("Error:"))
            .map(str::trim);
        if let Some(candidate) = candidate
            && !candidate.is_empty()
        {
            return Some(compact_verifier_failure_text(candidate, 160));
        }
    }
    output
        .lines()
        .map(str::trim)
        .find(|line| {
            !line.is_empty()
                && (line.contains("Error")
                    || line.contains("error")
                    || line.contains("FAILED")
                    || line.contains("Assertion"))
        })
        .map(|line| compact_verifier_failure_text(line, 160))
}

fn verifier_primary_exception_signature(output: &str) -> Option<String> {
    for line in output.lines() {
        let trimmed = line.trim();
        let candidate = trimmed
            .strip_prefix("E   ")
            .or_else(|| trimmed.strip_prefix("E "))
            .map(str::trim)
            .unwrap_or(trimmed);
        let exception = candidate
            .split_once(':')
            .map(|(head, _)| head)
            .unwrap_or(candidate);
        let exception = exception.trim();
        if exception.is_empty() || exception.starts_with("assert ") {
            continue;
        }
        let last_segment = exception.rsplit('.').next().unwrap_or(exception);
        let looks_like_exception = last_segment.ends_with("Error")
            || last_segment.ends_with("Exception")
            || last_segment == "Failed";
        if looks_like_exception
            && exception
                .chars()
                .all(|ch| ch.is_ascii_alphanumeric() || ch == '_' || ch == '.')
        {
            return Some(compact_verifier_failure_text(exception, 120));
        }
    }
    None
}

fn verifier_failed_tests_signature(output: &str) -> Option<String> {
    let framework = crate::tools::test_output::detect_framework(output);
    let failed_tests = crate::tools::test_output::parse_failed_tests(output, framework);
    if failed_tests.raw_count == 0 || failed_tests.names.is_empty() {
        return None;
    }
    let names = failed_tests
        .names
        .iter()
        .take(8)
        .map(String::as_str)
        .collect::<Vec<_>>()
        .join(",");
    Some(compact_verifier_failure_text(
        &format!("failed_tests:{}:{names}", failed_tests.raw_count),
        220,
    ))
}

fn verifier_failure_signature(
    output: &str,
    target_path: Option<&str>,
    target_line: Option<usize>,
    error_kind: Option<&str>,
) -> String {
    let mut parts = Vec::new();
    if let Some(path) = target_path {
        let mut path = path.to_string();
        if let Some(line) = target_line {
            path.push(':');
            path.push_str(&line.to_string());
        }
        parts.push(path);
    }
    if let Some(error_kind) = error_kind
        && !error_kind.is_empty()
    {
        parts.push(error_kind.to_string());
    }
    if parts.is_empty() {
        if let Some(line) = output.lines().map(str::trim).find(|line| !line.is_empty()) {
            parts.push(compact_verifier_failure_text(line, 160));
        } else {
            parts.push("verifier_failed".to_string());
        }
    }
    compact_verifier_failure_text(&parts.join(" "), 220)
}

fn compact_verifier_failure_text(input: &str, max_chars: usize) -> String {
    let masked = crate::session::feedback::mask_secrets(input);
    let collapsed = masked.split_whitespace().collect::<Vec<_>>().join(" ");
    truncate(&collapsed, max_chars)
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct VerifierDiagnosticAttemptSpec {
    model: String,
    timeout_secs: u64,
    role: &'static str,
}

fn verifier_diagnostic_attempt_spec(
    main_model: &str,
    sidecar_model: Option<&str>,
    attempts_done: usize,
) -> Option<VerifierDiagnosticAttemptSpec> {
    if attempts_done >= VERIFIER_DIAGNOSTIC_ATTEMPT_LIMIT {
        return None;
    }
    let sidecar = sidecar_model.filter(|model| *model != main_model);
    match (attempts_done, sidecar) {
        (0, Some(model)) => Some(VerifierDiagnosticAttemptSpec {
            model: model.to_string(),
            timeout_secs: VERIFIER_DIAGNOSTIC_SIDECAR_TIMEOUT_SECS,
            role: "sidecar",
        }),
        (0, None) => Some(VerifierDiagnosticAttemptSpec {
            model: main_model.to_string(),
            timeout_secs: VERIFIER_DIAGNOSTIC_MAIN_FALLBACK_TIMEOUT_SECS,
            role: "main",
        }),
        (1, Some(_)) => Some(VerifierDiagnosticAttemptSpec {
            model: main_model.to_string(),
            timeout_secs: VERIFIER_DIAGNOSTIC_MAIN_FALLBACK_TIMEOUT_SECS,
            role: "main_fallback",
        }),
        (1, None) | (2, _) => Some(VerifierDiagnosticAttemptSpec {
            model: main_model.to_string(),
            timeout_secs: VERIFIER_DIAGNOSTIC_MAIN_FALLBACK_TIMEOUT_SECS,
            role: "main_retry",
        }),
        _ => None,
    }
}

#[cfg(test)]
pub(super) fn verifier_repair_context_target_path(
    work_root: &Path,
    context: &super::repair_job::RepairJob,
) -> Option<PathBuf> {
    let hint = verifier_repair_effective_target_hint(context)?;
    resolve_user_path(work_root, &hint.path).ok()
}

pub(super) fn verifier_repair_effective_target_hint(
    context: &super::repair_job::RepairJob,
) -> Option<&super::task_contract::RecoveryTargetHint> {
    // Issue #647 (CB-007 / CB-015): when a `SemanticRepairPlan` is active
    // and the job is in the stale state (per `semantic_plan_is_stale`), the
    // freshly re-built `assessment.repair_target_hint` can be stale — the
    // re-diagnostic LLM commonly re-proposes the just-exhausted cluster
    // because the same failure text is still visible. `assign_semantic_plan_preserving_exhausted`
    // walks the new plan past the exhausted entry, but nothing rebuilds
    // the assessment hint to follow that walk. Returning the stale hint
    // would make the repair editor keep attacking the exhausted cluster.
    //
    // We deliberately do NOT try to map `assessment.repair_target_hint.path`
    // to a `FailureClusterKey` (no such mapping is recorded by the parser),
    // and we keep the legacy `semantic_plan = None` path bit-for-bit
    // identical so SetupRepair / pre-semantic flows are unaffected
    // (DR3-001 / "semantic_plan = None 経路は既存挙動" constraint).
    //
    // The CB-015 generation-aware rule (subsumes the legacy
    // `semantic_plan.is_some() && !exhausted_attempts.is_empty()`):
    //   stale (plan.gen >= job.gen, exhausted non-empty)
    //     → return None (force re-diagnostic against the current cluster).
    //   fresh (plan.gen < job.gen, post-re-diagnostic)
    //     → assessment has been refreshed for the current cluster; legacy
    //       behaviour stands and the controller can route to NeedFreshRead /
    //       NeedEdit.
    //   semantic_plan = None
    //     → legacy behaviour (unchanged).
    if super::repair_job::semantic_plan_is_stale(context) {
        return None;
    }
    // v0.4.10: once a semantic repair target has been exhausted for the
    // active cluster, do not let the legacy assessment fallback pick the same
    // path again. If another admitted target remains, use it; if all admitted
    // targets are exhausted, return None so the no-candidate / safe-stop path
    // can take over instead of falling back to an unrelated latest Read.
    if context.has_exhausted_repair_targets() {
        if let Some(next) = context.current_unexhausted_semantic_target() {
            return Some(next);
        }
        if context.current_semantic_targets_all_exhausted() {
            return None;
        }
    }
    if let Some(assessment) = context.assessment.as_ref() {
        if let Some(next) = assessment
            .repair_plan
            .get(context.applied_repair_intents.len())
        {
            return (!context.is_repair_hint_exhausted(next)).then_some(next);
        }
        return assessment
            .repair_target_hint
            .as_ref()
            .filter(|hint| !context.is_repair_hint_exhausted(hint));
    }
    None
}

/// Thin wrapper retained for in-file callers and existing tests. Delegates
/// to `repair_job::verifier_repair_decision`. The legacy `pending: bool`
/// argument is kept so the `Agent::task_contract_verifier_repair_pending`
/// flag and the repair-job presence remain decoupled at the call sites
/// (Issue #637: SSOT for the decision lives in `repair_job`).
#[cfg(test)]
fn verifier_repair_decision(
    pending: bool,
    context: Option<&super::repair_job::RepairJob>,
    messages: &[ConversationMessage],
    work_root: &Path,
    repair_edit_count: Option<usize>,
    repo_edit_calls_made_this_turn: usize,
) -> VerifierRepairDecision {
    repair_job::verifier_repair_decision(
        pending,
        context,
        messages,
        work_root,
        repair_edit_count,
        repo_edit_calls_made_this_turn,
    )
}

#[cfg(test)]
fn verifier_repair_policy_for_decision(decision: VerifierRepairDecision) -> EffectiveToolPolicy {
    match decision {
        VerifierRepairDecision::NeedDiagnostic => {
            EffectiveToolPolicy::restricted(EffectiveToolPolicyReason::VerifierRepair, Vec::new())
        }
        VerifierRepairDecision::DiagnosticUnavailable => {
            EffectiveToolPolicy::restricted(EffectiveToolPolicyReason::VerifierRepair, Vec::new())
        }
        VerifierRepairDecision::NeedFreshRead(target) => EffectiveToolPolicy::focused_edit(
            EffectiveToolPolicyReason::VerifierRepair,
            vec!["Read"],
            target,
            false,
        ),
        VerifierRepairDecision::NeedWrite(target) => EffectiveToolPolicy::focused_edit(
            EffectiveToolPolicyReason::VerifierRepair,
            vec!["Write"],
            target,
            false,
        ),
        VerifierRepairDecision::NeedEdit(target) => EffectiveToolPolicy::focused_edit(
            EffectiveToolPolicyReason::VerifierRepair,
            vec!["Edit"],
            target,
            true,
        ),
        VerifierRepairDecision::NeedTargetDiscovery => EffectiveToolPolicy::restricted(
            EffectiveToolPolicyReason::VerifierRepair,
            vec!["Read", "Glob", "Grep"],
        ),
        VerifierRepairDecision::NoRepair | VerifierRepairDecision::ReadyToVerify => {
            EffectiveToolPolicy::restricted(EffectiveToolPolicyReason::VerifierRepair, Vec::new())
        }
    }
}

fn verifier_repair_policy_for_target_hint(
    target_hint: &super::task_contract::RecoveryTargetHint,
    messages: &[ConversationMessage],
    work_root: &Path,
) -> EffectiveToolPolicy {
    let Some(relative) = super::repair_job::safe_relative_path_string(&target_hint.path) else {
        return EffectiveToolPolicy::restricted(
            EffectiveToolPolicyReason::VerifierRepair,
            Vec::new(),
        );
    };
    let target = work_root.join(relative);
    let target = std::fs::canonicalize(&target).unwrap_or(target);
    if !target.is_file() {
        return EffectiveToolPolicy::focused_edit(
            EffectiveToolPolicyReason::VerifierRepair,
            vec!["Write"],
            target,
            false,
        );
    }
    let target_already_read = focused_edit_target_already_read(messages, &target, work_root);
    if target_already_read {
        EffectiveToolPolicy::focused_edit(
            EffectiveToolPolicyReason::VerifierRepair,
            vec!["Edit"],
            target,
            true,
        )
    } else {
        EffectiveToolPolicy::focused_edit(
            EffectiveToolPolicyReason::VerifierRepair,
            vec!["Read"],
            target,
            false,
        )
    }
}

fn verifier_repair_target_display(target: &Path, work_root: &Path) -> String {
    target
        .strip_prefix(work_root)
        .unwrap_or(target)
        .to_string_lossy()
        .replace('\\', "/")
}

fn artifact_role_from_repo_edit_category(
    category: super::completion_evidence::RepoEditCategory,
) -> Option<super::task_contract::ArtifactRole> {
    match category {
        super::completion_evidence::RepoEditCategory::Impl => {
            Some(super::task_contract::ArtifactRole::Implementation)
        }
        super::completion_evidence::RepoEditCategory::Test => {
            Some(super::task_contract::ArtifactRole::Test)
        }
        super::completion_evidence::RepoEditCategory::Docs => {
            Some(super::task_contract::ArtifactRole::UsageDocs)
        }
        super::completion_evidence::RepoEditCategory::Setup => {
            Some(super::task_contract::ArtifactRole::Setup)
        }
        super::completion_evidence::RepoEditCategory::Other => None,
    }
}

fn synthesized_missing_implementation_target_path_for_request(
    role: super::task_contract::ArtifactRole,
    request: &str,
) -> Option<String> {
    if role != super::task_contract::ArtifactRole::Implementation {
        return None;
    }
    let lower = request.to_ascii_lowercase();
    if lower.contains("fastapi")
        || lower.contains("python")
        || lower.contains(".py")
        || request.contains("Pythonで")
        || request.contains("FastAPIで")
    {
        return Some("main.py".to_string());
    }
    if lower.contains("rust")
        || lower.contains("cargo")
        || request.contains("Rustで")
        || request.contains("Rust")
    {
        if lower.contains("library")
            || lower.contains("crate")
            || request.contains("ライブラリ")
            || request.contains("クレート")
        {
            return Some("src/lib.rs".to_string());
        }
        return Some("src/main.rs".to_string());
    }
    None
}

fn synthesized_missing_test_target_path_for_request(
    request: &str,
) -> Option<(&'static str, &'static str)> {
    let lower = request.to_ascii_lowercase();
    if lower.contains("rust")
        || lower.contains("cargo test")
        || lower.contains("cargo")
        || request.contains("Rustで")
    {
        return Some(("tests/main.rs", "rust"));
    }
    if lower.contains("typescript") || lower.contains("type script") || lower.contains(".ts") {
        return Some(("tests/main.test.ts", "typescript"));
    }
    if lower.contains("javascript") || lower.contains("node") || lower.contains("npm test") {
        return Some(("tests/main.test.js", "javascript"));
    }
    if lower.contains("fastapi")
        || lower.contains("flask")
        || lower.contains("django")
        || lower.contains("python")
        || lower.contains("pytest")
        || lower.contains(".py")
        || request.contains("Pythonで")
        || request.contains("FastAPIで")
    {
        return Some(("tests/test_main.py", "python"));
    }
    None
}

fn test_target_path_compatible_with_request(path: &str, request: &str) -> bool {
    let Some((target_path, _)) = synthesized_missing_test_target_path_for_request(request) else {
        return true;
    };
    let expected_ext = std::path::Path::new(target_path)
        .extension()
        .and_then(|ext| ext.to_str());
    let actual_ext = std::path::Path::new(path)
        .extension()
        .and_then(|ext| ext.to_str());
    expected_ext == actual_ext
}

fn missing_verifier_setup_hint_for_request(request: &str) -> Option<&'static str> {
    let lower = request.to_ascii_lowercase();
    if lower.contains("rust")
        || lower.contains("cargo")
        || request.contains("Rust")
        || request.contains("cargo test")
    {
        return Some("For Rust/Cargo workspaces, create or update Cargo.toml.");
    }
    if lower.contains("python")
        || lower.contains("pytest")
        || lower.contains("fastapi")
        || lower.contains("flask")
        || lower.contains("django")
        || request.contains("Python")
        || request.contains("FastAPI")
    {
        return Some(
            "For Python/pytest workspaces, create or update pyproject.toml, requirements.txt, or pytest configuration.",
        );
    }
    if lower.contains("node")
        || lower.contains("npm")
        || lower.contains("typescript")
        || lower.contains("javascript")
    {
        return Some("For Node/npm workspaces, create or update package.json with a test script.");
    }
    None
}

fn sha256_hex(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

const DETERMINISTIC_FRAMEWORK_APP_FALLBACK_MARKER: &str =
    "Materialized deterministic framework app fallback files";

fn deterministic_framework_game_impl_path(path: &Path) -> bool {
    matches!(
        path.to_string_lossy().as_ref(),
        "app.vue" | "src/App.tsx" | "src/app/page.tsx" | "app/page.tsx" | "src/routes/+page.svelte"
    )
}

fn deterministic_support_target_relative(work_root: &Path, relative: &Path) -> PathBuf {
    if let Ok(rest) = relative.strip_prefix("src/app")
        && work_root.join("app").is_dir()
    {
        return PathBuf::from("app").join(rest);
    }
    if let Ok(rest) = relative.strip_prefix("app")
        && work_root.join("src/app").is_dir()
    {
        return PathBuf::from("src/app").join(rest);
    }
    relative.to_path_buf()
}

fn meaningful_workspace_files(work_root: &Path, limit: usize) -> Option<Vec<PathBuf>> {
    let mut files = Vec::new();
    collect_meaningful_workspace_files(work_root, work_root, limit, &mut files).ok()?;
    Some(files)
}

fn collect_meaningful_workspace_files(
    root: &Path,
    current: &Path,
    limit: usize,
    files: &mut Vec<PathBuf>,
) -> std::io::Result<()> {
    if files.len() > limit {
        return Ok(());
    }
    for entry in std::fs::read_dir(current)? {
        let entry = entry?;
        let name = entry.file_name();
        let name = name.to_string_lossy();
        // Issue #646 (E1): single SSOT for ignored workspace directories.
        if super::task_workspace_scope::is_workspace_ignored_dir(&name) {
            continue;
        }
        let path = entry.path();
        if path.is_dir() {
            collect_meaningful_workspace_files(root, &path, limit, files)?;
        } else if path.is_file()
            && let Ok(relative) = path.strip_prefix(root)
        {
            files.push(relative.to_path_buf());
            if files.len() > limit {
                return Ok(());
            }
        }
    }
    Ok(())
}

fn should_apply_repo_change_quality_gate(
    action_expectation: recovery::ActionExpectation,
    active_task_expects_repo_change: bool,
    mode: ExecutionMode,
) -> bool {
    mode == ExecutionMode::Act
        && (action_expectation == recovery::ActionExpectation::RepoChange
            || active_task_expects_repo_change)
}

fn is_page_component_target(relative: &str) -> bool {
    matches!(relative, "app/page.tsx" | "src/app/page.tsx")
        || relative.ends_with("/app/page.tsx")
        || relative.ends_with("/src/app/page.tsx")
}

fn focused_edit_guidance_note(
    target: &Path,
    work_root: &Path,
    target_already_read: bool,
) -> String {
    let path = target
        .strip_prefix(work_root)
        .unwrap_or(target)
        .to_string_lossy()
        .replace('\\', "/");
    if target_already_read {
        format!(
            "[Focused Edit Recovery] The target file {path} has already been read. The only available tool for this turn is Edit. Do not call Read again. Use exactly one compact Edit on that file now. Replace only one contiguous block from the last Read. Do not attempt a full-file rewrite, multi-file change, scaffold command, or dev-server command."
        )
    } else if !target.is_file() {
        format!(
            "[Focused Edit Recovery] The target file {path} does not exist yet. The only available tool for this turn is Write on that exact path. Do not call Read, Bash, Glob, or Grep; create the missing artifact directly and keep the body focused on the requested role."
        )
    } else {
        format!(
            "[Focused Edit Recovery] Keep this turn minimal. If you need context, do one Read on {path} first; otherwise use exactly one compact Edit. Do not attempt a full-file rewrite, multi-file change, scaffold command, or dev-server command. Replace only one contiguous block from the last Read and move the implementation forward with the first concrete slice."
        )
    }
}

fn focused_edit_guidance_note_for_policy(
    policy: &EffectiveToolPolicy,
    target: &Path,
    work_root: &Path,
    target_already_read: bool,
) -> String {
    if policy.reason() == EffectiveToolPolicyReason::VerifierRepair {
        let path = target
            .strip_prefix(work_root)
            .unwrap_or(target)
            .to_string_lossy()
            .replace('\\', "/");
        match policy.allowed_tool_names_for_prompt() {
            Some(["Read"]) => {
                return format!(
                    "[Verifier Repair] The verifier failure target is {path}, but the current file contents have not been read since the latest target edit. The only available tool for this turn is Read. Emit exactly one Read on that file now. Do not call Edit, Bash, Glob, Grep, or answer in prose."
                );
            }
            Some(["Edit"]) => {
                return format!(
                    "[Verifier Repair] The verifier failure target is {path} and its current contents have been read. The only available tool for this turn is Edit. Emit exactly one compact Edit on that file now. Do not call Read again, Bash, or answer in prose."
                );
            }
            Some(["Write"]) => {
                return format!(
                    "[Verifier Repair] The verifier failure target {path} is missing. The only available tool for this turn is Write on that exact path. Do not call Read, Bash, Glob, Grep, or answer in prose."
                );
            }
            _ => {}
        }
    }
    focused_edit_guidance_note(target, work_root, target_already_read)
}

fn focused_edit_compact_anchor_note(target: &Path, work_root: &Path) -> String {
    let path = target
        .strip_prefix(work_root)
        .unwrap_or(target)
        .to_string_lossy()
        .replace('\\', "/");
    format!(
        "[Focused Edit Recovery / Compact Anchor] The Read result for {path} is intentionally only a tiny exact anchor from the real file, not the whole file. Use that anchor only for `old_string`. Keep `new_string` similarly small: at most 3 lines and under 240 characters. Do not insert imports, hooks, component definitions, or full-file content. If the anchor is CTA or placeholder text, replace only that text with a short task-specific label or copy."
    )
}

fn focused_edit_first_slice_note(
    messages: &[ConversationMessage],
    target: &Path,
    work_root: &Path,
    target_already_read: bool,
) -> Option<String> {
    if !target_already_read {
        return None;
    }
    let relative = target
        .strip_prefix(work_root)
        .unwrap_or(target)
        .to_string_lossy()
        .replace('\\', "/");
    if is_page_component_target(&relative) {
        if let Some(old_string) = latest_page_copy_block_from_read(messages, target, work_root) {
            return Some(recovery::first_scaffold_shell_edit_exact_anchor_note(
                &relative,
                &old_string,
            ));
        }
        return Some(recovery::first_scaffold_shell_edit_note(&relative));
    }
    None
}

fn focused_edit_first_slice_uses_exact_anchor(
    messages: &[ConversationMessage],
    target: &Path,
    work_root: &Path,
    target_already_read: bool,
) -> bool {
    if !target_already_read {
        return false;
    }
    let relative = target
        .strip_prefix(work_root)
        .unwrap_or(target)
        .to_string_lossy()
        .replace('\\', "/");
    is_page_component_target(&relative)
        && latest_page_copy_block_from_read(messages, target, work_root).is_some()
}

fn focused_edit_exact_recovery_anchor(
    messages: &[ConversationMessage],
    target: &Path,
    work_root: &Path,
    target_already_read: bool,
    successful_repo_edits: usize,
) -> Option<String> {
    match successful_repo_edits {
        0 => {
            if !focused_edit_first_slice_uses_exact_anchor(
                messages,
                target,
                work_root,
                target_already_read,
            ) {
                return None;
            }
            latest_page_copy_block_from_read(messages, target, work_root)
        }
        1 => {
            let relative = target
                .strip_prefix(work_root)
                .unwrap_or(target)
                .to_string_lossy()
                .replace('\\', "/");
            if !target_already_read || !is_page_component_target(&relative) {
                return None;
            }
            latest_page_intro_copy_line_from_read(messages, target, work_root)
        }
        _ => None,
    }
}

fn focused_edit_second_slice_note(
    messages: &[ConversationMessage],
    target: &Path,
    work_root: &Path,
    target_already_read: bool,
) -> Option<String> {
    if !target_already_read {
        return None;
    }
    let relative = target
        .strip_prefix(work_root)
        .unwrap_or(target)
        .to_string_lossy()
        .replace('\\', "/");
    if !is_page_component_target(&relative) {
        return None;
    }
    latest_page_intro_copy_line_from_read(messages, target, work_root).map(|old_string| {
        recovery::second_scaffold_shell_edit_exact_anchor_note(&relative, &old_string)
    })
}

fn latest_page_copy_block_from_read(
    messages: &[ConversationMessage],
    target: &Path,
    work_root: &Path,
) -> Option<String> {
    let (_, tool) = latest_read_exchange_for_target(messages, target, work_root)?;
    extract_page_copy_block_from_numbered_read(&tool.content)
}

fn latest_page_intro_copy_line_from_read(
    messages: &[ConversationMessage],
    target: &Path,
    work_root: &Path,
) -> Option<String> {
    let (_, tool) = latest_read_exchange_for_target(messages, target, work_root)?;
    extract_page_intro_copy_line_from_numbered_read(&tool.content)
        .or_else(|| extract_page_intro_paragraph_from_numbered_read(&tool.content))
}

fn focused_edit_compact_recovery_anchor(
    messages: &[ConversationMessage],
    target: &Path,
    work_root: &Path,
) -> Option<String> {
    let (_, tool) = latest_read_exchange_for_target(messages, target, work_root)?;
    extract_compact_edit_anchor_from_numbered_read(&tool.content)
}

fn extract_compact_edit_anchor_from_numbered_read(contents: &str) -> Option<String> {
    let lines = contents
        .lines()
        .map(strip_read_line_number_prefix)
        .collect::<Vec<_>>();
    let candidate = |line: &&String| {
        let trimmed = line.trim();
        !trimmed.is_empty()
            && !matches!(trimmed, "{" | "}" | ");" | "</div>" | "</main>")
            && line.chars().count() <= 180
    };

    lines
        .iter()
        .find(|line| {
            candidate(line)
                && matches!(
                    line.trim(),
                    "Deploy Now" | "Documentation" | "Get started" | "Learn More"
                )
        })
        .or_else(|| {
            lines.iter().find(|line| {
                let trimmed = line.trim_start();
                candidate(line)
                    && (trimmed.starts_with("<button ")
                        || trimmed.starts_with("<a ")
                        || trimmed.starts_with("<h1 ")
                        || trimmed.starts_with("<p "))
            })
        })
        .or_else(|| {
            lines.iter().find(|line| {
                let trimmed = line.trim_start();
                candidate(line)
                    && !trimmed.starts_with("import ")
                    && !trimmed.starts_with("export default")
            })
        })
        .cloned()
}

fn extract_page_copy_block_from_numbered_read(contents: &str) -> Option<String> {
    let lines = contents
        .lines()
        .map(strip_read_line_number_prefix)
        .collect::<Vec<_>>();
    let start = lines.iter().position(|line| {
        let trimmed = line.trim_start();
        trimmed.starts_with("<h1 ") || trimmed.starts_with("<h1>")
    })?;
    let end = lines
        .iter()
        .enumerate()
        .skip(start)
        .find_map(|(index, line)| line.trim_start().contains("</h1>").then_some(index))?;
    Some(lines[start..=end].join("\n"))
}

fn extract_page_intro_paragraph_from_numbered_read(contents: &str) -> Option<String> {
    let lines = contents
        .lines()
        .map(strip_read_line_number_prefix)
        .collect::<Vec<_>>();
    let start = lines.iter().position(|line| {
        let trimmed = line.trim_start();
        trimmed.starts_with("<p ") || trimmed.starts_with("<p>")
    })?;
    let end = lines
        .iter()
        .enumerate()
        .skip(start)
        .find_map(|(index, line)| line.trim_start().contains("</p>").then_some(index))?;
    Some(lines[start..=end].join("\n"))
}

fn extract_page_intro_copy_line_from_numbered_read(contents: &str) -> Option<String> {
    let lines = contents
        .lines()
        .map(strip_read_line_number_prefix)
        .collect::<Vec<_>>();
    let start = lines.iter().position(|line| {
        let trimmed = line.trim_start();
        trimmed.starts_with("<p ") || trimmed.starts_with("<p>")
    })?;
    let end = lines
        .iter()
        .enumerate()
        .skip(start)
        .find_map(|(index, line)| line.trim_start().contains("</p>").then_some(index))?;

    lines[start + 1..end]
        .iter()
        .find(|line| {
            let trimmed = line.trim();
            !trimmed.is_empty()
                && !trimmed.starts_with('<')
                && trimmed.chars().any(|ch| ch.is_alphabetic())
        })
        .cloned()
}

fn strip_read_line_number_prefix(line: &str) -> String {
    let trimmed = line.trim_start();
    if let Some((prefix, rest)) = trimmed.split_once(": ")
        && !prefix.is_empty()
        && prefix.chars().all(|ch| ch.is_ascii_digit())
    {
        return rest.to_string();
    }
    line.to_string()
}

pub(super) fn focused_edit_target_already_read(
    messages: &[ConversationMessage],
    target: &Path,
    work_root: &Path,
) -> bool {
    latest_read_exchange_for_target(messages, target, work_root).is_some()
}

fn focused_edit_history(
    messages: &[ConversationMessage],
    target: &Path,
    work_root: &Path,
) -> Vec<ConversationMessage> {
    let mut filtered = Vec::new();
    if let Some(note) = messages.iter().rev().find(|message| {
        message.role == "system" && message.content.trim_start().starts_with("[Act Mode /")
    }) {
        filtered.push(note.clone());
    }
    if let Some(user) = messages.iter().rev().find(|message| message.role == "user") {
        filtered.push(user.clone());
    }
    if let Some((assistant, tool)) = latest_read_exchange_for_target(messages, target, work_root) {
        filtered.push(assistant);
        filtered.push(tool);
    }
    filtered
}

fn focused_edit_minimal_history(messages: &[ConversationMessage]) -> Vec<ConversationMessage> {
    let mut filtered = Vec::new();
    if let Some(note) = messages.iter().rev().find(|message| {
        message.role == "system" && message.content.trim_start().starts_with("[Act Mode /")
    }) {
        filtered.push(note.clone());
    }
    if let Some(user) = messages.iter().rev().find(|message| message.role == "user") {
        filtered.push(user.clone());
    }
    filtered
}

fn focused_edit_exact_anchor_history(
    messages: &[ConversationMessage],
    target: &Path,
    work_root: &Path,
    anchor: &str,
) -> Vec<ConversationMessage> {
    let mut filtered = focused_edit_minimal_history(messages);
    let relative = target
        .strip_prefix(work_root)
        .unwrap_or(target)
        .to_string_lossy()
        .replace('\\', "/");
    filtered.push(ConversationMessage::assistant(
        String::new(),
        vec![ToolCall {
            id: "focused-anchor-read".to_string(),
            name: "Read".to_string(),
            arguments: serde_json::json!({ "path": relative }),
        }],
    ));
    filtered.push(ConversationMessage::tool(
        "Read".to_string(),
        format_numbered_read_block(anchor),
    ));
    filtered
}

fn format_numbered_read_block(contents: &str) -> String {
    contents
        .lines()
        .enumerate()
        .map(|(index, line)| format!("{:>4}: {line}", index + 1))
        .collect::<Vec<_>>()
        .join("\n")
}

#[derive(Debug, Clone)]
struct ToolExchange {
    result_index: Option<usize>,
    tool_call: ToolCall,
    result: Option<ConversationMessage>,
}

fn tool_exchanges(messages: &[ConversationMessage]) -> Vec<ToolExchange> {
    let mut exchanges = Vec::new();
    for (assistant_index, message) in messages.iter().enumerate() {
        if message.role != "assistant" || message.tool_calls.is_empty() {
            continue;
        }

        let mut result_index = assistant_index + 1;
        for tool_call in &message.tool_calls {
            let result = messages
                .get(result_index)
                .filter(|candidate| candidate.role == "tool")
                .cloned();
            let exchange_result_index = result.as_ref().map(|_| result_index);
            if result.is_some() {
                result_index += 1;
            }
            exchanges.push(ToolExchange {
                result_index: exchange_result_index,
                tool_call: tool_call.clone(),
                result,
            });
        }
    }
    exchanges
}

fn tool_call_path_matches_target(tool_call: &ToolCall, target: &Path, work_root: &Path) -> bool {
    let Some(path) = tool_call
        .arguments
        .get("path")
        .and_then(serde_json::Value::as_str)
    else {
        return false;
    };
    tool_path_matches_target(path, target, work_root)
}

fn exchange_is_successful_read_for_target(
    exchange: &ToolExchange,
    target: &Path,
    work_root: &Path,
) -> bool {
    exchange_is_successful_named_tool_for_target(exchange, &["Read"], target, work_root)
}

fn exchange_is_successful_write_or_edit_for_target(
    exchange: &ToolExchange,
    target: &Path,
    work_root: &Path,
) -> bool {
    exchange_is_successful_named_tool_for_target(exchange, &["Write", "Edit"], target, work_root)
}

fn exchange_is_successful_named_tool_for_target(
    exchange: &ToolExchange,
    tool_names: &[&str],
    target: &Path,
    work_root: &Path,
) -> bool {
    tool_names.contains(&exchange.tool_call.name.as_str())
        && tool_call_path_matches_target(&exchange.tool_call, target, work_root)
        && exchange.result.as_ref().is_some_and(|result| {
            result.role == "tool"
                && result.name.as_deref() == Some(exchange.tool_call.name.as_str())
                && !result.content.trim_start().starts_with("Error:")
        })
}

pub(super) fn latest_successful_read_existing_path(
    messages: &[ConversationMessage],
    work_root: &Path,
    after_message_index: Option<usize>,
) -> Option<PathBuf> {
    let mut latest_existing = None;
    for exchange in tool_exchanges(messages).into_iter().rev() {
        if let Some(after_message_index) = after_message_index
            && exchange
                .result_index
                .is_none_or(|result_index| result_index <= after_message_index)
        {
            continue;
        }
        if exchange.tool_call.name != "Read" {
            continue;
        }
        if !exchange.result.as_ref().is_some_and(|result| {
            result.role == "tool"
                && result.name.as_deref() == Some("Read")
                && !result.content.trim_start().starts_with("Error:")
        }) {
            continue;
        }
        let Some(path) = exchange
            .tool_call
            .arguments
            .get("path")
            .and_then(serde_json::Value::as_str)
        else {
            continue;
        };
        let Ok(candidate) = resolve_user_path(work_root, path) else {
            continue;
        };
        if !candidate.is_file() {
            continue;
        }
        latest_existing.get_or_insert_with(|| candidate.clone());
        if is_preferred_read_edit_target(&candidate) {
            return Some(candidate);
        }
    }
    latest_existing
}

pub(super) fn latest_verifier_repair_note_index(messages: &[ConversationMessage]) -> Option<usize> {
    messages.iter().rposition(|message| {
        message.role == "system"
            && (message.content.contains("task_contract_verify_attempt=")
                || message
                    .content
                    .contains("task_contract_verify_edit_attempt=")
                || message
                    .content
                    .contains("task_contract_verify_discovery_attempt=")
                || message
                    .content
                    .contains("task_contract_verify_read_attempt="))
    })
}

/// Issue #660 (Phase C / DD-5 / Stage 4 DR4-001/002) — pure builder that
/// renders an `ActiveJobSelection` to the `agent.active_job.selected`
/// payload. The payload schema (proposed to #666) is:
///
/// ```json
/// {
///   "iteration_seq": <u32>,
///   "selected": {
///     "job_kind": "<kind>|None",
///     "desired_action": "<short type label>",
///     "policy_reason": "<EffectiveToolPolicyReason::as_str()>",
///     "allowed_tools_count": <u32>,
///     "target_path_hash": "<hex16>|null"
///   },
///   "rejected": [{"job_kind": "<kind>", "rejection_reason": "LowerPriority|BudgetExhausted"}],
///   "policy_projected": {"reason_label": "<...>", "allowed_tool_kinds": <u32>},
///   "budget_state": {"repair_attempts": <u32>, "artifact_attempts": <u32>}
/// }
/// ```
///
/// **Security invariants** (§7 of design policy):
/// - Raw verifier commands NEVER appear; `DesiredAction::VerifierRepair`
///   collapses to the static label `"verifier_repair"` only.
/// - Raw `PathBuf` targets NEVER appear; `target_path_hash` is the
///   non-cryptographic correlator `crate::logging::stable_path_hash(
///   mask_secrets(...))` (Issue #661 DR1-002: SSOT promoted from the
///   prior `stable_path_hash_for_active_job` private helper to
///   `logging.rs` so #659/#660/#661 path_hash values share one SSOT).
/// - `log_llm_event` re-applies `mask_payload_inplace` as the final
///   defense line.
pub(super) fn build_active_job_selected_payload(
    selection: &super::active_job_arbiter::ActiveJobSelection,
    iteration_seq: u32,
    repair_attempts: u32,
    artifact_attempts: u32,
) -> serde_json::Value {
    let projected_policy = super::active_job_arbiter::project_policy(selection);
    let policy_reason_label = projected_policy.reason().as_str();
    let allowed_tool_kinds = projected_policy
        .allowed_tool_names_for_prompt()
        .map(|t| t.len() as u32)
        .unwrap_or(0);

    let selected_block = match selection.selected.as_ref() {
        Some(candidate) => {
            let target_path_hash = candidate
                .desired_action
                .target_path()
                .map(|path| {
                    // Stage 4 DR4-001: never emit the raw path. The mask
                    // pass catches inline credentials; the hash gives
                    // dataset consumers a stable correlator without
                    // leaking the literal path.
                    let masked =
                        crate::session::feedback::mask_secrets(&path.display().to_string());
                    serde_json::Value::String(stable_path_hash(&masked))
                })
                .unwrap_or(serde_json::Value::Null);
            serde_json::json!({
                "job_kind": candidate.kind.as_str(),
                "desired_action": candidate.desired_action.label(),
                "policy_reason": candidate.policy.reason().as_str(),
                "allowed_tools_count": candidate
                    .policy
                    .allowed_tool_names_for_prompt()
                    .map(|t| t.len() as u32)
                    .unwrap_or(0),
                "target_path_hash": target_path_hash,
            })
        }
        None => serde_json::json!({
            "job_kind": "None",
            "desired_action": serde_json::Value::Null,
            "policy_reason": projected_policy.reason().as_str(),
            "allowed_tools_count": allowed_tool_kinds,
            "target_path_hash": serde_json::Value::Null,
        }),
    };

    let rejected_block: Vec<serde_json::Value> = selection
        .rejected
        .iter()
        .map(|rj| {
            // DR1-004: `RejectionReason` only has `LowerPriority` and
            // `BudgetExhausted` — both reduce to a single static label
            // without leaking external strings.
            let reason_label = match rj.reason {
                super::active_job_arbiter::RejectionReason::LowerPriority { .. } => "LowerPriority",
                super::active_job_arbiter::RejectionReason::BudgetExhausted { .. } => {
                    "BudgetExhausted"
                }
            };
            serde_json::json!({
                "job_kind": rj.kind.as_str(),
                "rejection_reason": reason_label,
            })
        })
        .collect();

    serde_json::json!({
        "iteration_seq": iteration_seq,
        "selected": selected_block,
        "rejected": rejected_block,
        "policy_projected": {
            "reason_label": policy_reason_label,
            "allowed_tool_kinds": allowed_tool_kinds,
        },
        "budget_state": {
            "repair_attempts": repair_attempts,
            "artifact_attempts": artifact_attempts,
        },
    })
}

// Issue #661 DR1-002 / DR2-005: the previous `stable_path_hash_for_active_job`
// private helper has been removed and `build_active_job_selected_payload`
// now uses `crate::logging::stable_path_hash` directly. The hash algorithm
// (16-hex `DefaultHasher`) is unchanged, so `agent.active_job.selected`
// payload `target_path_hash` values remain byte-for-byte identical with
// pre-migration emissions.

/// Issue #661 iteration-4 Task 5.2 (DR1-005 / Section 8-1): pure builder for
/// the `agent.verifier.invoked` event payload. Extracted as a free function
/// so unit tests can assert the field shape without instantiating an Agent.
///
/// Payload schema (Section 8-1, `mask_payload_inplace` post-application form):
///
/// ```json
/// {
///   "session_id": "<SessionStore::session_id()>",
///   "turn_index": <usize>,
///   "iteration_seq": <usize>,
///   "runner": "cargo" | "python3",
///   "bound_artifacts": [{ "path_hash": "<16-hex>" }],
///   "bound_test_artifacts_count": <usize>,
///   "bound_artifacts_truncated": <bool>,
///   "env_summary": {
///     "allowlist_keys": [<&str>],
///     "pythonpath_root": <bool>
///   },
///   "cwd_inside_work_root": <bool>
/// }
/// ```
///
/// `cwd_inside_work_root` is intentionally a **root-level** field even though
/// the `HermeticEnvSummary` struct carries it. Section 8-1 specifies the
/// flatten so log consumers can pivot on cwd containment without descending
/// into `env_summary`. `env_summary` only carries `allowlist_keys` /
/// `pythonpath_root`.
///
/// Field order matches the schema documentation so `serde_json::to_vec`
/// (used by `compute_payload_digest`) sees a stable canonical byte sequence
/// for identical inputs across re-emits in the same turn (DR1-004 dedup
/// determinism).
pub(super) fn build_agent_verifier_invoked_payload(
    session_id: &str,
    turn_index: usize,
    iteration_seq: usize,
    snapshot: &super::auto_test::VerifierInvokedSnapshot,
) -> serde_json::Value {
    let bound_artifacts: Vec<serde_json::Value> = snapshot
        .bound_artifacts
        .iter()
        .map(|h| serde_json::json!({ "path_hash": h.as_str() }))
        .collect();
    let env_summary = serde_json::json!({
        "allowlist_keys": snapshot.env_summary.allowlist_keys,
        "pythonpath_root": snapshot.env_summary.pythonpath_root,
    });
    serde_json::json!({
        "session_id": session_id,
        "turn_index": turn_index,
        "iteration_seq": iteration_seq,
        "runner": snapshot.runner.as_str(),
        "bound_artifacts": bound_artifacts,
        "bound_test_artifacts_count": snapshot.bound_test_artifacts_count,
        "bound_artifacts_truncated": snapshot.bound_artifacts_truncated,
        "env_summary": env_summary,
        // Root-level (NOT inside env_summary) per Section 8-1 schema.
        "cwd_inside_work_root": snapshot.env_summary.cwd_inside_work_root,
    })
}

/// Issue #661 iteration-5 Task 7.3: pure-fn builder for the
/// `agent.verifier.external_import_rejected` event payload (Section 8-2 schema).
///
/// raw module name / raw filesystem path / raw executable path は payload に
/// 出さない (DR4-005)。caller (`emit_agent_verifier_external_import_rejected_if_first`)
/// が事前に `mask_secrets` + `stable_path_hash` 経由で hash 化した文字列のみを
/// `detected_hashes` 経由で受け取る。`detected_modules` は最大
/// `EXTERNAL_IMPORT_DETECTED_CAP` 件 (8) で truncate される。
pub(super) fn build_agent_verifier_external_import_rejected_payload(
    session_id: &str,
    turn_index: usize,
    runner: &str,
    reason: &str,
    detected_hashes: &[(&str, &'static str)],
    detected_count: usize,
    detected_truncated: bool,
) -> serde_json::Value {
    let cap = super::auto_test::EXTERNAL_IMPORT_DETECTED_CAP;
    let detected_modules: Vec<serde_json::Value> = detected_hashes
        .iter()
        .take(cap)
        .map(|(hash, source_kind)| {
            serde_json::json!({
                "module_hash": *hash,
                "path_hash": *hash,
                "source_kind": *source_kind,
            })
        })
        .collect();
    serde_json::json!({
        "session_id": session_id,
        "turn_index": turn_index,
        "runner": runner,
        "reason": reason,
        "detected_count": detected_count,
        "detected_truncated": detected_truncated,
        "detected_modules": detected_modules,
    })
}

fn focused_edit_tool_policy_error(
    name: &str,
    arguments: &serde_json::Value,
    target: &Path,
    work_root: &Path,
    target_already_read: bool,
) -> Option<String> {
    let path_display = target
        .strip_prefix(work_root)
        .unwrap_or(target)
        .to_string_lossy()
        .replace('\\', "/");
    let path_matches = arguments
        .get("path")
        .and_then(serde_json::Value::as_str)
        .is_some_and(|raw_path| tool_path_matches_target(raw_path, target, work_root));
    let rejected_tool = compact_tool_name_for_policy_feedback(name);

    if !target.is_file() {
        if name != "Write" || !path_matches {
            return Some(format!(
                "focused edit recovery rejected {rejected_tool}; only allows Write on missing target {path_display}"
            ));
        }
        return None;
    }

    if target_already_read {
        if name != "Edit" || !path_matches {
            return Some(format!(
                "focused edit recovery rejected {rejected_tool}; only allows Edit on {path_display} after the file has already been read"
            ));
        }
        return None;
    }

    match name {
        "Read" | "Edit" if path_matches => None,
        _ => Some(format!(
            "focused edit recovery rejected {rejected_tool}; only allows Read or Edit on {path_display} until the first edit succeeds"
        )),
    }
}

/// Legacy non-scope wrapper kept for unit tests and tests-only re-exports.
/// Production code MUST use [`effective_tool_policy_error_for_call_with_scope`]
/// so the MissingVerifierJob scope gate fires (Issue #646 A1/A3).
#[cfg(test)]
fn effective_tool_policy_error_for_call(
    policy: &EffectiveToolPolicy,
    name: &str,
    arguments: &serde_json::Value,
    work_root: &Path,
) -> Option<String> {
    effective_tool_policy_error_for_call_with_scope(policy, name, arguments, work_root, None)
}

/// Issue #646 (A1/A3): scope-aware variant. When `scope` is provided and the
/// policy is a `VerifierRepair`-reasoned restricted policy WITHOUT a
/// focused-edit or artifact-directed target (i.e. the MissingVerifierJob
/// fallback whitelist), the file-targeting tool calls must additionally pass
/// `scope.contains(...)` on the resolved path argument. Out-of-scope writes
/// are rejected even though `Write`/`Edit`/`Bash` would otherwise satisfy
/// the tool-name whitelist.
fn effective_tool_policy_error_for_call_with_scope(
    policy: &EffectiveToolPolicy,
    name: &str,
    arguments: &serde_json::Value,
    work_root: &Path,
    scope: Option<&super::task_workspace_scope::TaskWorkspaceScope>,
) -> Option<String> {
    if let Some(allowed_tools) = policy.allowed_tool_names_for_prompt()
        && !allowed_tools.contains(&name)
    {
        // Issue #664 iteration-3 (CB2-003): when the LLM calls `Bash`
        // under an artifact-directed recovery policy (Read/Write/Edit-
        // only allow set), the allow-list check fires *before* the
        // SetupBootstrap branch below could classify the rejection as a
        // BashOutOfPolicy. To keep the caller-side string-match in
        // `execute_tool_call_with_optional_policy_resolution` reachable
        // (which routes the rejection through
        // `record_artifact_completion_bash_violation` so the structured
        // report emits `category = "bash_out_of_policy"`), we emit the
        // same `"artifact-directed recovery rejected Bash"` shape that
        // the artifact-directed path uses. Otherwise the rejection
        // would surface as the generic `"tool policy rejected Bash"`
        // string and the BashOutOfPolicy branch would be unreachable.
        if policy.reason() == EffectiveToolPolicyReason::ArtifactDirectedRecovery && name == "Bash"
        {
            let target_display = policy_target_path(policy)
                .map(|target| {
                    target
                        .strip_prefix(work_root)
                        .unwrap_or(target)
                        .to_string_lossy()
                        .replace('\\', "/")
                })
                .unwrap_or_else(|| "the active target".to_string());
            return Some(format!(
                "artifact-directed recovery rejected Bash; only allows Read, Write, or Edit on {target_display}"
            ));
        }
        return Some(restricted_tool_policy_error(
            policy,
            name,
            allowed_tools,
            work_root,
        ));
    }

    // Issue #664 (DS1-001 二段防衛): SetupBootstrap allows `Bash` only at
    // the tool-name layer, but `cargo test` / `echo hi` / `curl ...` would
    // pass the allowlist. The command-level allow set is decided here via
    // `crate::tools::bash::is_setup_command`. Non-Setup commands are
    // rejected with a clear error.
    if policy.reason() == EffectiveToolPolicyReason::SetupBootstrap && name == "Bash" {
        let Some(command) = arguments.get("command").and_then(serde_json::Value::as_str) else {
            return Some("setup bootstrap bash requires a string `command` argument".to_string());
        };
        if !crate::tools::bash::is_setup_command(command) {
            return Some(
                "setup bootstrap only allows dependency-install Bash commands (BashCommandClass::EnvSetup)"
                    .to_string(),
            );
        }
    }

    if let Some(focused) = policy.focused_edit_policy() {
        return focused_edit_tool_policy_error(
            name,
            arguments,
            &focused.target,
            work_root,
            focused.target_already_read,
        );
    }

    if let Some(artifact) = policy.artifact_directed_policy() {
        return artifact_directed_tool_policy_error(name, arguments, &artifact.target, work_root);
    }

    // Issue #646 (A1/A3): MissingVerifierJob fallback scope enforcement.
    if policy.reason() == EffectiveToolPolicyReason::VerifierRepair
        && let Some(scope) = scope
        && let Some(err) = missing_verifier_scope_policy_error(name, arguments, work_root, scope)
    {
        return Some(err);
    }

    None
}

/// Issue #646 (C2 / A4): no-op repo-edit detector. Compares the pre-tool
/// content hash captured in `execute_tool_call` against the post-tool
/// content hash. When both are `Some(x)` with equal values the Write/Edit
/// did not modify the file and MUST NOT promote the path to `Owned`.
///
/// Returns `false` whenever the pre-tool hash is missing (first observation
/// in the turn) or `None` (file didn't exist before the tool call), since
/// those are real edits.
fn is_repo_edit_no_op(pre_tool_hash: Option<&str>, current_hash: Option<&str>) -> bool {
    matches!((pre_tool_hash, current_hash), (Some(p), Some(c)) if p == c)
}

/// Issue #646 (A1/A3): rejects file-targeting tool calls whose resolved path
/// argument falls outside the active `TaskWorkspaceScope`. Applies only when
/// the policy reason is `VerifierRepair` and the policy carries no specific
/// target (i.e. the MissingVerifierJob whitelist case).
fn missing_verifier_scope_policy_error(
    name: &str,
    arguments: &serde_json::Value,
    work_root: &Path,
    scope: &super::task_workspace_scope::TaskWorkspaceScope,
) -> Option<String> {
    if !matches!(name, "Write" | "Edit") {
        return None;
    }
    let raw_path = arguments.get("path").and_then(serde_json::Value::as_str)?;
    let relative = workspace_relative_path_for_tool_arg(work_root, raw_path)?;
    if scope.contains(&relative) {
        return None;
    }
    let rejected_tool = compact_tool_name_for_policy_feedback(name);
    Some(format!(
        "MissingVerifierJob policy rejected {rejected_tool}; path {relative} is outside the active workspace scope"
    ))
}

fn artifact_directed_tool_policy_error(
    name: &str,
    arguments: &serde_json::Value,
    target: &Path,
    work_root: &Path,
) -> Option<String> {
    // CB-003: SSOT target match — compare on the workspace-relative
    // canonical form derived from `resolve_user_path` (used by both
    // `task_workspace_scope` and `ArtifactCompletionJob.target_path`).
    // The legacy `tool_path_matches_target` fell back to `target` and
    // `resolved` directly when `std::fs::canonicalize` failed, which
    // diverged from the missing-leaf handling in `ArtifactCompletionJob`
    // (CB-001 / CB-003). Using the workspace-relative SSOT keeps the
    // policy gate and the job constructor in lock-step on symlink and
    // missing-file edge cases.
    let path_matches = arguments
        .get("path")
        .and_then(serde_json::Value::as_str)
        .is_some_and(|raw_path| {
            tool_path_matches_target_via_workspace_ssot(raw_path, target, work_root)
        });
    if path_matches {
        return None;
    }

    let rejected_tool = compact_tool_name_for_policy_feedback(name);
    let path_display = target
        .strip_prefix(work_root)
        .unwrap_or(target)
        .to_string_lossy()
        .replace('\\', "/");
    Some(format!(
        "artifact-directed recovery rejected {rejected_tool}; only allows Read, Write, or Edit on {path_display}"
    ))
}

/// CB-003 / CB2-002: SSOT target match for the artifact-directed policy
/// gate.
///
/// Routes both the tool argument and the policy target through the
/// same `workspace_relative_path_for_tool_arg` helper used by the
/// rest of the workspace-scope SSOT. The strings are then compared
/// for byte equality. When either side fails to resolve (absolute
/// path, parent traversal, symlink escape, missing canonical
/// resolution, or **dangling-symlink ancestor**), the call returns
/// `false` — defensive default that matches `ArtifactCompletionJob::new`.
///
/// CB2-002: the workspace-relative helper relies on
/// `safety::path_guard::canonicalize_with_missing_tail`, which walks
/// ancestors with `Path::exists()`. A dangling symlink ancestor has
/// `exists()=false` (the link target is absent), so the walker would
/// silently skip past it. We add an explicit `symlink_metadata` /
/// `canonicalize` re-check on the input path's ancestor chain so the
/// policy gate refuses to confer write permission through any path
/// whose ancestor is a dangling symlink, matching the job
/// constructor's behavior at construction time.
fn tool_path_matches_target_via_workspace_ssot(
    raw_path: &str,
    target: &Path,
    work_root: &Path,
) -> bool {
    let Some(input_rel) = workspace_relative_path_for_tool_arg(work_root, raw_path) else {
        return false;
    };
    // Derive the target's workspace-relative form via the same SSOT.
    // The target was originally produced by
    // `Agent::artifact_recovery_target_path` (= `resolve_user_path` on
    // a workspace-relative `current_artifact_recovery_target.path`),
    // so going back through `workspace_relative_path_for_tool_arg`
    // gives a stable, canonical-prefix-stripped string we can byte-
    // compare against the tool argument's relative form.
    let target_str = target.to_string_lossy();
    let Some(target_rel) = workspace_relative_path_for_tool_arg(work_root, &target_str) else {
        return false;
    };
    if input_rel != target_rel {
        return false;
    }
    // CB2-002: defensive ancestor-chain re-check for both sides. A
    // dangling-symlink ancestor would otherwise be skipped by the
    // `Path::exists()`-based walk inside `resolve_user_path`, and
    // both sides would byte-compare equal even though the parent
    // could be flipped between validation and execution. By
    // rejecting any side whose nearest existing ancestor is a
    // dangling symlink, the gate stays consistent with
    // `ArtifactCompletionJob::new`.
    // PR-002 SSOT: route through
    // `artifact_ownership::nearest_existing_ancestor_within_work_root`
    // so the canonicalize policy lives in a single module.
    if !ancestor_chain_has_no_dangling_symlinks(work_root, raw_path) {
        return false;
    }
    if !ancestor_chain_has_no_dangling_symlinks(work_root, &target_str) {
        return false;
    }
    true
}

/// PR-002 (Issue #652) thin adapter that turns a raw tool-argument path
/// (relative-or-absolute string) into the canonical candidate path that
/// the SSOT helper `artifact_ownership::
/// nearest_existing_ancestor_within_work_root` accepts. The canonicalize
/// policy itself lives in `artifact_ownership` — this wrapper exists only
/// because the tool-argument call-site has the path as `&str` and may
/// pass an absolute path verbatim, while `ArtifactCompletionJob::new`
/// always provides a `work_root.join(relative_path)` `PathBuf`.
fn ancestor_chain_has_no_dangling_symlinks(work_root: &Path, raw_path: &str) -> bool {
    let input = Path::new(raw_path);
    let candidate: PathBuf = if input.is_absolute() {
        input.to_path_buf()
    } else {
        work_root.join(input)
    };
    super::artifact_ownership::nearest_existing_ancestor_within_work_root(work_root, &candidate)
}

fn restricted_tool_policy_error(
    policy: &EffectiveToolPolicy,
    name: &str,
    allowed_tools: &[&str],
    work_root: &Path,
) -> String {
    let rejected_tool = compact_tool_name_for_policy_feedback(name);
    let allowed = if allowed_tools.is_empty() {
        "none".to_string()
    } else {
        allowed_tools.join(", ")
    };
    let mut message = format!(
        "tool policy rejected {rejected_tool}; allowed tools: {allowed}; reason: {}",
        policy.reason().as_str()
    );
    if let Some(target) = policy_target_path(policy) {
        let path_display = target
            .strip_prefix(work_root)
            .unwrap_or(target)
            .to_string_lossy()
            .replace('\\', "/");
        message.push_str("; target: ");
        message.push_str(&path_display);
    }
    message
}

fn policy_target_path(policy: &EffectiveToolPolicy) -> Option<&Path> {
    policy
        .focused_edit_policy()
        .map(|focused| focused.target.as_path())
        .or_else(|| {
            policy
                .artifact_directed_policy()
                .map(|artifact| artifact.target.as_path())
        })
}

fn compact_tool_name_for_policy_feedback(name: &str) -> String {
    let mut compact = name
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '_' | '-'))
        .take(32)
        .collect::<String>();
    if compact.is_empty() {
        compact.push_str("unknown-tool");
    }
    compact
}

fn focused_edit_policy_violation_feedback_note(
    unresolved_errors: &[String],
    allowed_tools: Option<&[&str]>,
    target_display: Option<&str>,
) -> Option<String> {
    let error = unresolved_errors.iter().rev().find(|error| {
        let is_policy_error = error.starts_with("focused edit recovery rejected ")
            || error.starts_with("focused edit recovery only allows ")
            || error.starts_with("artifact-directed recovery rejected ")
            || error.starts_with("tool policy rejected ");
        is_policy_error && target_display.is_none_or(|target| error.contains(target))
    })?;
    let allowed = allowed_tools
        .filter(|tools| !tools.is_empty())
        .map(|tools| tools.join(", "))
        .unwrap_or_else(|| "none".to_string());
    Some(format!(
        "[Focused Edit Policy Violation] Previous tool call was rejected and was not executed: {error}. Allowed tools now: {allowed}. Emit exactly one allowed tool call on the required target path; do not call omitted tools."
    ))
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum FocusedEditBatchAction {
    Accept,
    TruncateToFirst,
    Reject(String),
}

fn focused_edit_tool_batch_action(
    tool_calls: &[ToolCall],
    target: &Path,
    work_root: &Path,
    target_already_read: bool,
) -> FocusedEditBatchAction {
    let Some(first_tool_call) = tool_calls.first() else {
        return FocusedEditBatchAction::Accept;
    };

    let first_call_error = focused_edit_tool_policy_error(
        &first_tool_call.name,
        &first_tool_call.arguments,
        target,
        work_root,
        target_already_read,
    );

    if tool_calls.len() == 1 {
        return first_call_error
            .map(FocusedEditBatchAction::Reject)
            .unwrap_or(FocusedEditBatchAction::Accept);
    }

    if first_call_error.is_none() {
        FocusedEditBatchAction::TruncateToFirst
    } else {
        FocusedEditBatchAction::Reject(first_call_error.unwrap_or_default())
    }
}

/// Legacy non-scope wrapper kept for unit tests and tests-only re-exports.
/// Production code MUST use [`effective_tool_batch_action_with_scope`].
#[cfg(test)]
fn effective_tool_batch_action(
    tool_calls: &[ToolCall],
    policy: &EffectiveToolPolicy,
    work_root: &Path,
) -> FocusedEditBatchAction {
    effective_tool_batch_action_with_scope(tool_calls, policy, work_root, None)
}

/// Issue #646 (A1/A3): scope-aware variant of [`effective_tool_batch_action`].
/// Forwarded scope is consulted only by the MissingVerifierJob fallback
/// branch inside `effective_tool_policy_error_for_call_with_scope`.
fn effective_tool_batch_action_with_scope(
    tool_calls: &[ToolCall],
    policy: &EffectiveToolPolicy,
    work_root: &Path,
    scope: Option<&super::task_workspace_scope::TaskWorkspaceScope>,
) -> FocusedEditBatchAction {
    let Some(first_tool_call) = tool_calls.first() else {
        return FocusedEditBatchAction::Accept;
    };

    if let Some(err) = effective_tool_policy_error_for_call_with_scope(
        policy,
        &first_tool_call.name,
        &first_tool_call.arguments,
        work_root,
        scope,
    ) {
        return FocusedEditBatchAction::Reject(err);
    }

    if let Some(focused) = policy.focused_edit_policy() {
        return focused_edit_tool_batch_action(
            tool_calls,
            &focused.target,
            work_root,
            focused.target_already_read,
        );
    }

    if policy.artifact_directed_policy().is_some() && tool_calls.len() > 1 {
        return FocusedEditBatchAction::TruncateToFirst;
    }

    FocusedEditBatchAction::Accept
}

fn tool_path_matches_target(raw_path: &str, target: &Path, work_root: &Path) -> bool {
    let Ok(resolved) = resolve_user_path(work_root, raw_path) else {
        return false;
    };
    let canonical_target = std::fs::canonicalize(target).unwrap_or_else(|_| {
        target
            .strip_prefix(work_root)
            .ok()
            .and_then(|relative| resolve_user_path(work_root, &relative.to_string_lossy()).ok())
            .unwrap_or_else(|| target.to_path_buf())
    });
    let canonical_resolved = std::fs::canonicalize(&resolved).unwrap_or(resolved);
    canonical_resolved == canonical_target
}

fn focused_read_target_for_directory(resolved: &Path, target: &Path) -> bool {
    if !resolved.is_dir() {
        return false;
    }
    let Some(parent) = target.parent() else {
        return false;
    };
    let canonical_resolved =
        std::fs::canonicalize(resolved).unwrap_or_else(|_| resolved.to_path_buf());
    let canonical_parent = std::fs::canonicalize(parent).unwrap_or_else(|_| parent.to_path_buf());
    canonical_resolved == canonical_parent
}

fn latest_read_exchange_for_target(
    messages: &[ConversationMessage],
    target: &Path,
    work_root: &Path,
) -> Option<(ConversationMessage, ConversationMessage)> {
    let exchanges = tool_exchanges(messages);
    for exchange in exchanges.iter().rev() {
        if !exchange_is_successful_read_for_target(exchange, target, work_root) {
            continue;
        }
        let result_index = exchange.result_index?;
        if exchanges.iter().any(|later| {
            later
                .result_index
                .is_some_and(|later_index| later_index > result_index)
                && exchange_is_successful_write_or_edit_for_target(later, target, work_root)
        }) {
            continue;
        }
        let assistant =
            ConversationMessage::assistant(String::new(), vec![exchange.tool_call.clone()]);
        let tool_message = exchange.result.clone()?;
        return Some((assistant, tool_message));
    }
    None
}

fn plan_sections_with_content(contents: &str) -> Vec<&'static str> {
    [
        "Goal",
        "Constraints",
        "First Action",
        "Verification",
        "Deliverables",
        "Acceptance Criteria",
        "Quality Bar",
        "Execution Plan",
        "Verification Plan",
        "Risks / Fallbacks",
    ]
    .into_iter()
    .filter(|section| plan_section_has_content(contents, section))
    .collect()
}

fn plan_section_body_for_progress<'a>(contents: &'a str, section: &str) -> Option<&'a str> {
    let mut start = None;
    let mut end = contents.len();
    let mut offset = 0usize;
    for line in contents.lines() {
        let trimmed = line.trim();
        if let Some(heading) = trimmed.strip_prefix("## ") {
            if start.is_some() {
                end = offset;
                break;
            }
            if normalize_plan_heading_for_progress(heading) == section {
                start = Some(offset + line.len());
            }
        }
        offset += line.len() + 1;
    }
    start.map(|idx| &contents[idx..end])
}

fn plan_section_excerpt(contents: &str, sections: &[&str]) -> Option<String> {
    for section in sections {
        let Some(body) = plan_section_body_for_progress(contents, section) else {
            continue;
        };
        for line in body.lines().map(str::trim) {
            if line.is_empty()
                || line == "-"
                || matches!(
                    line,
                    "1." | "2."
                        | "3."
                        | "1. First slice:"
                        | "2. Next phases:"
                        | "3. Review checkpoint:"
                )
            {
                continue;
            }
            let cleaned = line.trim_start_matches("- ").trim();
            return Some(format!(
                "{section}: {}",
                truncate(&sanitize_for_progress(cleaned), 72)
            ));
        }
    }
    None
}

fn plan_phase_from_sections(
    sections: &[&str],
    current_stage: PlanStage,
    approval_ready: bool,
) -> &'static str {
    if approval_ready {
        "Approval review"
    } else if sections.iter().any(|section| {
        matches!(
            *section,
            "First Action"
                | "Verification"
                | "Execution Plan"
                | "Verification Plan"
                | "Risks / Fallbacks"
        )
    }) {
        "Define next action"
    } else if sections
        .iter()
        .any(|section| matches!(*section, "Acceptance Criteria" | "Quality Bar"))
    {
        "Define quality bar"
    } else if sections
        .iter()
        .any(|section| matches!(*section, "Goal" | "Constraints" | "Deliverables"))
    {
        "Draft foundation"
    } else {
        match current_stage {
            PlanStage::Stage1 => "Draft foundation",
            PlanStage::Stage2 => "Define next action",
            PlanStage::Stage3 => "Approval review",
            PlanStage::Ready => "Approval review",
        }
    }
}

fn summarize_plan_read(contents: &str) -> (String, Option<String>) {
    let missing = lifecycle::plan_missing_sections(contents);
    if missing.is_empty() {
        (
            "Review completed plan".to_string(),
            Some("Approval ready; review the final plan before /approve".to_string()),
        )
    } else {
        let next = lifecycle::plan_next_stage_sections(contents);
        let note = if !next.is_empty() {
            format!("Next focus: {}", join_sections_for_progress(&next))
        } else {
            format!("Missing: {}", join_sections_for_progress(&missing))
        };
        ("Review plan draft".to_string(), Some(note))
    }
}

fn summarize_plan_write(
    tool_name: &str,
    raw_path: &str,
    new_text: &str,
    work_root: &Path,
    plan_path: Option<&Path>,
    current_stage: PlanStage,
) -> PlanWriteSummary {
    let previous = if raw_path.is_empty() {
        String::new()
    } else if plan_path_matches(raw_path, work_root, plan_path) {
        plan_path
            .and_then(|path| std::fs::read_to_string(path).ok())
            .unwrap_or_default()
    } else {
        resolve_user_path(work_root, raw_path)
            .ok()
            .and_then(|path| std::fs::read_to_string(path).ok())
            .unwrap_or_default()
    };
    let previous_sections = plan_sections_with_content(&previous);
    let current_sections = plan_sections_with_content(new_text);
    let changed_sections = current_sections
        .iter()
        .copied()
        .filter(|section| {
            let old_body = plan_section_body_for_progress(&previous, section).unwrap_or_default();
            let new_body = plan_section_body_for_progress(new_text, section).unwrap_or_default();
            sanitize_for_progress(old_body) != sanitize_for_progress(new_body)
        })
        .collect::<Vec<_>>();
    let added_sections = current_sections
        .iter()
        .copied()
        .filter(|section| !previous_sections.contains(section))
        .collect::<Vec<_>>();
    let removed_sections = previous_sections
        .iter()
        .copied()
        .filter(|section| !current_sections.contains(section))
        .collect::<Vec<_>>();
    let focus_sections = if !changed_sections.is_empty() {
        changed_sections.clone()
    } else if !current_sections.is_empty() {
        current_sections.clone()
    } else {
        Vec::new()
    };
    let verb = if !removed_sections.is_empty() {
        "Rewrite"
    } else if previous_sections.is_empty() {
        "Draft"
    } else if !added_sections.is_empty() {
        "Add"
    } else if tool_name == "Edit" {
        "Revise"
    } else {
        "Update"
    };
    let action = if focus_sections.is_empty() {
        "Update plan draft".to_string()
    } else {
        format!("{verb} {}", join_sections_for_progress(&focus_sections))
    };
    let note = plan_section_excerpt(new_text, &focus_sections).or_else(|| {
        let fallback = current_sections.clone();
        plan_section_excerpt(new_text, &fallback)
    });
    let delta = new_text.len() as isize - previous.len() as isize;
    let next = lifecycle::plan_next_stage_sections(new_text);
    let approval_ready = lifecycle::plan_missing_sections(new_text).is_empty();
    let status = if approval_ready {
        Some(format!("Approval ready | delta {delta:+}B"))
    } else if !next.is_empty() {
        Some(format!(
            "Next: {} | delta {delta:+}B",
            join_sections_for_progress(&next)
        ))
    } else {
        Some(format!("delta {delta:+}B"))
    };
    let phase =
        plan_phase_from_sections(&focus_sections, current_stage, approval_ready).to_string();
    let signature = format!("{}|{}|{}", phase, action, note.clone().unwrap_or_default());
    PlanWriteSummary {
        action,
        note,
        status,
        phase,
        signature,
    }
}

fn tool_display(
    tool_name: &str,
    arguments: &serde_json::Value,
    work_root: &std::path::Path,
    plan_path: Option<&Path>,
    current_stage: PlanStage,
    arg_budget: usize,
) -> ProgressDisplay {
    let str_arg = |key: &str| -> &str {
        arguments
            .get(key)
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default()
    };
    let raw_path = str_arg("path");
    let path_display = progress_path_display(raw_path, work_root, plan_path, arg_budget.max(48));
    match tool_name {
        "Write" => {
            let content = arguments
                .get("content")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();
            let (action, note, status) = if plan_path_matches(raw_path, work_root, plan_path) {
                let summary = summarize_plan_write(
                    "Write",
                    raw_path,
                    content,
                    work_root,
                    plan_path,
                    current_stage,
                );
                (summary.action, summary.note, summary.status)
            } else {
                (
                    "Write file".to_string(),
                    (!text_preview(content, 72).is_empty())
                        .then(|| format!("Preview: {}", text_preview(content, 72))),
                    arguments
                        .get("content")
                        .and_then(serde_json::Value::as_str)
                        .map(|c| format!("{}B", c.len())),
                )
            };
            ProgressDisplay {
                action,
                path: Some(path_display),
                note,
                status,
            }
        }
        "Edit" => {
            let new_text = arguments
                .get("new_string")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();
            let (action, note, status) = if plan_path_matches(raw_path, work_root, plan_path) {
                let summary = summarize_plan_write(
                    "Edit",
                    raw_path,
                    new_text,
                    work_root,
                    plan_path,
                    current_stage,
                );
                (summary.action, summary.note, summary.status)
            } else {
                (
                    "Revise file".to_string(),
                    (!text_preview(new_text, 72).is_empty())
                        .then(|| format!("Preview: {}", text_preview(new_text, 72))),
                    None,
                )
            };
            ProgressDisplay {
                action,
                path: Some(path_display),
                note,
                status,
            }
        }
        "Read" => {
            let line_suffix = read_line_suffix(arguments);
            let path = format!("{path_display}{line_suffix}");
            let (action, note, status) = if plan_path_matches(raw_path, work_root, plan_path) {
                let contents = plan_path
                    .and_then(|path| std::fs::read_to_string(path).ok())
                    .unwrap_or_default();
                let (action, note) = summarize_plan_read(&contents);
                let status = if lifecycle::current_plan_stage(&contents) == PlanStage::Ready {
                    Some("Approval ready".to_string())
                } else {
                    let next = lifecycle::plan_next_stage_sections(&contents);
                    (!next.is_empty()).then(|| {
                        format!(
                            "Current phase: {}",
                            plan_phase_from_sections(&next, current_stage, false)
                        )
                    })
                };
                (action, note, status)
            } else if !line_suffix.is_empty() {
                let (preview, extra) = read_preview(raw_path, work_root);
                (
                    format!("Read lines {}", line_suffix.trim_start_matches(':')),
                    preview.map(|preview| format!("Preview: {preview}")),
                    extra,
                )
            } else {
                let (preview, extra) = read_preview(raw_path, work_root);
                (
                    "Read file".to_string(),
                    preview.map(|preview| format!("Preview: {preview}")),
                    extra,
                )
            };
            ProgressDisplay {
                action,
                path: Some(compact_progress_path(&path, arg_budget.max(48))),
                note,
                status,
            }
        }
        "Bash" => {
            let sanitized = sanitize_for_progress(str_arg("command"));
            ProgressDisplay {
                action: format!("Run {}", truncate(&sanitized, arg_budget.saturating_sub(4))),
                path: None,
                note: None,
                status: None,
            }
        }
        "Glob" | "Grep" => ProgressDisplay {
            action: format!(
                "Search {}",
                truncate(
                    &sanitize_for_progress(str_arg("pattern")),
                    arg_budget.saturating_sub(7)
                )
            ),
            path: None,
            note: None,
            status: None,
        },
        _ => ProgressDisplay {
            action: truncate(&sanitize_for_progress(tool_name), arg_budget),
            path: None,
            note: None,
            status: None,
        },
    }
}

fn plan_section_has_content(contents: &str, target: &str) -> bool {
    let mut in_section = false;
    for line in contents.lines() {
        let trimmed = line.trim();
        if let Some(heading) = trimmed.strip_prefix("## ") {
            in_section = normalize_plan_heading_for_progress(heading) == target;
            continue;
        }
        if !in_section {
            continue;
        }
        if trimmed.is_empty()
            || trimmed == "-"
            || matches!(
                trimmed,
                "1." | "2."
                    | "3."
                    | "1. First slice:"
                    | "2. Next phases:"
                    | "3. Review checkpoint:"
            )
        {
            continue;
        }
        return true;
    }
    false
}

fn normalize_plan_heading_for_progress(heading: &str) -> &str {
    match heading.trim() {
        "Next Step" | "First Step" | "Execution Plan" | "実行計画" | "実装計画"
        | "実装フェーズ" => "First Action",
        "Verification Plan" | "検証計画" => "Verification",
        "Risks/Fallbacks" => "Risks / Fallbacks",
        "リスク/フォールバック" | "リスク・フォールバック" | "リスク / フォールバック" => {
            "Risks / Fallbacks"
        }
        other => other,
    }
}

fn read_line_suffix(arguments: &serde_json::Value) -> String {
    let start = arguments
        .get("start_line")
        .and_then(serde_json::Value::as_u64);
    let end = arguments
        .get("end_line")
        .and_then(serde_json::Value::as_u64);
    match (start, end) {
        (Some(start), Some(end)) if start == end => format!(":{start}"),
        (Some(start), Some(end)) => format!(":{start}-{end}"),
        (Some(start), None) => format!(":{start}-"),
        (None, Some(end)) => format!(":1-{end}"),
        (None, None) => String::new(),
    }
}

fn text_preview(text: &str, max_chars: usize) -> String {
    let collapsed = sanitize_for_progress(text)
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ");
    truncate(&collapsed, max_chars)
}

fn read_preview(raw_path: &str, work_root: &Path) -> (Option<String>, Option<String>) {
    if raw_path.is_empty() {
        return (None, None);
    }
    let Ok(path) = resolve_user_path(work_root, raw_path) else {
        return (None, None);
    };
    let Ok(metadata) = std::fs::metadata(&path) else {
        return (None, None);
    };
    if !metadata.is_file() || metadata.len() > 64 * 1024 {
        return (None, None);
    }
    let Ok(contents) = std::fs::read_to_string(&path) else {
        return (None, None);
    };
    let preview = text_preview(&contents, 50);
    (
        (!preview.is_empty()).then_some(preview),
        Some(format!("{}B", metadata.len())),
    )
}

fn compact_progress_path(path: &str, max_chars: usize) -> String {
    let char_count = path.chars().count();
    if char_count <= max_chars {
        return path.to_string();
    }
    if let Some((_, suffix)) = path.rsplit_once("/plans/") {
        let collapsed = format!(".../plans/{suffix}");
        if collapsed.chars().count() <= max_chars {
            return collapsed;
        }
    }
    let keep = max_chars.saturating_sub(3);
    let tail = path
        .chars()
        .rev()
        .take(keep)
        .collect::<String>()
        .chars()
        .rev()
        .collect::<String>();
    format!("...{tail}")
}

/// Compute the argument-summary budget for a progress line given the current
/// terminal width (issue #432 §4.3.1).
///
/// Subtracts the fixed chrome (`[iter N/M]  `, optional emoji, tool name, and
/// the two-space separator) plus 3 chars reserved for the `...` ellipsis that
/// `truncate()` appends when the input exceeds the budget, then clamps the
/// result to `MIN_ARG_BUDGET` (20). When `cols` is `None` (footer disabled /
/// handle absent / first-tick race) the caller falls back to
/// `DEFAULT_ARG_BUDGET` (57), preserving the pre-#432 behaviour.
pub(super) fn progress_available_width(
    cols: Option<u16>,
    tool_name: &str,
    iter_human: usize,
    max_iterations: usize,
    use_unicode: bool,
) -> usize {
    const DEFAULT_ARG_BUDGET: usize = 57;
    const MIN_ARG_BUDGET: usize = 20;
    // truncate() appends "..." (3 chars) when it fires, so reserve those chars
    // up-front. Otherwise a fully-truncated Bash command overflows cols by 3.
    const ELLIPSIS_RESERVE: usize = 3;

    let Some(cols) = cols else {
        return DEFAULT_ARG_BUDGET;
    };

    // Chrome must stay in sync with the `format!` in `format_progress_line`:
    //   "[iter N/M]  " + (emoji " ")? + tool_name + "  "
    let iter_prefix = format!("[iter {iter_human}/{max_iterations}]  ");
    let emoji_width = if use_unicode {
        tool_emoji(tool_name).chars().count() + 1
    } else {
        0
    };
    let chrome = iter_prefix.len() + emoji_width + tool_name.chars().count() + 2;

    (cols as usize)
        .saturating_sub(chrome)
        .saturating_sub(ELLIPSIS_RESERVE)
        .max(MIN_ARG_BUDGET)
}

/// Format a single-line per-iteration progress line. ANSI color is only
/// applied to the tool name when `use_color` is true, and emoji is prepended
/// when `use_unicode` is true. `cols` is the current terminal width from the
/// footer broadcaster; `None` falls back to the pre-#432 fixed budget.
fn progress_detail_budget(cols: Option<u16>, prefix: &str) -> usize {
    cols.map(|value| value as usize)
        .unwrap_or(96)
        .saturating_sub(prefix.chars().count())
        .max(24)
}

fn format_progress_field(prefix: &str, value: &str, cols: Option<u16>) -> String {
    let budget = progress_detail_budget(cols, prefix);
    format!(
        "{prefix}{}",
        truncate(&sanitize_for_progress(value), budget)
    )
}

#[allow(clippy::too_many_arguments)]
pub(super) fn format_progress_line(
    tool_name: &str,
    arguments: &serde_json::Value,
    iter_human: usize,
    max_iterations: usize,
    work_root: &std::path::Path,
    use_color: bool,
    use_unicode: bool,
    cols: Option<u16>,
    plan_path: Option<&Path>,
    current_stage: PlanStage,
    status_prefix: Option<&str>,
    stage_label: Option<&str>,
) -> String {
    let arg_budget =
        progress_available_width(cols, tool_name, iter_human, max_iterations, use_unicode);
    let display = tool_display(
        tool_name,
        arguments,
        work_root,
        plan_path,
        current_stage,
        arg_budget,
    );
    // Sanitize before painting so an adversarial tool_name cannot inject escapes.
    // emoji は &'static str ハードコードなので再 sanitize は不要。
    let safe_tool_name = sanitize_for_progress(tool_name);
    let label = if use_unicode {
        format!("{} {}", tool_emoji(tool_name), safe_tool_name)
    } else {
        safe_tool_name
    };
    let painted = paint(&label, tool_color(tool_name), use_color);
    if matches!(tool_name, "Read" | "Write" | "Edit") {
        let mut lines = Vec::new();
        let stage = stage_label.unwrap_or("Working");
        lines.push(format!("[iter {iter_human}/{max_iterations}] {stage}"));
        lines.push(format!("  tool:   {painted}"));
        lines.push(format_progress_field("  action: ", &display.action, cols));
        if let Some(path) = display.path {
            lines.push(format_progress_field("  file:   ", &path, cols));
        }
        if let Some(note) = display.note {
            lines.push(format_progress_field("  note:   ", &note, cols));
        }
        if let Some(status) = display.status {
            let combined_status = status_prefix
                .map(|prefix| format!("{prefix} | {status}"))
                .unwrap_or(status);
            lines.push(format_progress_field("  status: ", &combined_status, cols));
        } else if let Some(prefix) = status_prefix {
            lines.push(format_progress_field("  status: ", prefix, cols));
        }
        lines.push(String::new());
        lines.join("\n")
    } else {
        format!(
            "[iter {iter_human}/{max_iterations}]  {painted}  {}",
            display.action
        )
    }
}

#[allow(clippy::too_many_arguments)]
fn format_blocked_progress_line(
    tool_name: &str,
    arguments: &serde_json::Value,
    iter_human: usize,
    max_iterations: usize,
    work_root: &std::path::Path,
    use_color: bool,
    use_unicode: bool,
    cols: Option<u16>,
    headline: &str,
    note: &str,
    plan_path: Option<&Path>,
    current_stage: PlanStage,
) -> String {
    let arg_budget =
        progress_available_width(cols, headline, iter_human, max_iterations, use_unicode);
    let display = tool_display(
        tool_name,
        arguments,
        work_root,
        plan_path,
        current_stage,
        arg_budget,
    );
    let label = if use_unicode {
        format!("⛔ {headline}")
    } else {
        headline.to_string()
    };
    let painted = paint(&label, "\x1b[38;5;196m", use_color);
    if matches!(tool_name, "Read" | "Write" | "Edit") {
        let mut lines = Vec::new();
        lines.push(format!("[iter {iter_human}/{max_iterations}] {headline}"));
        lines.push(format!("  tool:   {painted}"));
        lines.push(format_progress_field("  action: ", &display.action, cols));
        if let Some(path) = display.path {
            lines.push(format_progress_field("  file:   ", &path, cols));
        }
        lines.push(format_progress_field("  status: ", note, cols));
        lines.push(String::new());
        lines.join("\n")
    } else {
        format!(
            "[iter {iter_human}/{max_iterations}]  {painted}  {}",
            display.action
        )
    }
}

/// Issue #555: build `recent_tool_summary` for the photon mapper from the
/// last `MAX_CONTEXT_PACK_RECENT_TOOLS` assistant messages that contain tool
/// calls. Only the call name and JSON-serialised arguments are captured;
/// tool result messages are intentionally excluded (no stdout/stderr).
fn build_recent_tool_summary(
    messages: &[crate::session::store::ConversationMessage],
) -> Vec<crate::photon::mapper::RecentToolCall> {
    use crate::photon::mapper::{MAX_CONTEXT_PACK_RECENT_TOOLS, RecentToolCall};

    messages
        .iter()
        .rev()
        .filter(|m| m.role == "assistant" && !m.tool_calls.is_empty())
        .flat_map(|m| m.tool_calls.iter())
        .take(MAX_CONTEXT_PACK_RECENT_TOOLS)
        .map(|tc| RecentToolCall {
            name: tc.name.clone(),
            args_summary: tc.arguments.to_string(),
        })
        .collect()
}

